INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jkrumm/hetzner-vps/cloudflare', 'cloudflare', 'jkrumm', 'hetzner-vps', 'community', 'cloudflare jkrumm hetzner-vps community Cloudflare AIエージェント提供Production Docker Compose栈，支持Hetzner VPS、RollHook、Traefik、Postgres、Valkey和OTel Cloudflare AIエージェントは、Hetzner VPS、RollHook、Traefik、Postgres、Valkey、OTelをサポートするProduction Docker Composeスタックを提供 Cloudflare AI 에이전트는 Hetzner VPS, RollHook, Traefik, Postgres, Valkey, OTel을 지원하는 Production Docker Compose 스택을 제공 Cloudflare es una herramienta de AI que mejora la seguridad y el rendimiento de tu stack de producción con Docker Compose en Hetzner VPS Cloudflare est un outil d''IA qui améliore la sécurité et les performances de votre stack de production avec Docker Compose sur Hetzner VPS Cloudflare ist ein KI-Tool, das die Sicherheit und Leistung Ihres Produktionsstacks mit Docker Compose auf Hetzner VPS verbessert O Cloudflare é uma ferramenta de segurança e desempenho para aplicações web, que pode ser usada com Docker Compose, Traefik e Postgres Cloudflare — это инструмент безопасности и производительности для веб-приложений, который можно использовать с Docker Compose, Traefik и Postgres Cloudflare هي أداة أمان وأداء لل تطبيقات الوب، يمكن استخدامها مع Docker Compose و Traefik و Postgres Production Docker Compose stack for Hetzner VPS — RollHook, Traefik, Postgres, Valkey, OTel Cloudflare AIエージェント Docker Compose Hetzner VPS RollHook Traefik Postgres Valkey OTel Production环境 Cloudflare AIエージェント安装 Production Docker Compose stack for Hetzner VPS — RollHook, Traefik, Postgres, Valkey, OTel');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Moffran/calibrated_explanations/ce-pipeline-builder', 'community', 'Moffran', 'calibrated_explanations', 'Moffran/calibrated_explanations', 'ce-pipeline-builder', 74, 12, 39, '2026-03-02T20:43:37Z', '2026-03-03T01:59:21.145Z', 'ae2def778a6daa118ec4edef1a02444ce848e06818b61839b8d66f2ab0efd276', '{"id":"Moffran/calibrated_explanations/ce-pipeline-builder","name":"ce-pipeline-builder","description":{"zh":"CE Pipeline Builder是一个AI代理技能，专门用于实现校准解释方法。它帮助开发者构建可靠的CI/CD管道，集成Python工具进行模型解释，并提供自动化测试功能。","ja":"CE Pipeline Builderは、キャリブレーション説明手法を実装するためのAIエージェントスキルです。信頼性の高いCI/CDパイプラインの構築、Pythonツールによるモデル説明の統合、自動テスト機能を提供します。","ko":"CE Pipeline Builder는 보정 설명 방법을 구현하기 위한 AI 에이전트 스킬입니다. 신뢰할 수 있는 CI/CD 파이프라인 구축, Python 도구를 통한 모델 설명 통합, 자동화된 테스트 기능을 제공합니다.","es":"Ce-pipeline-builder es un repositorio para el método de explicaciones calibradas, ayudando a los desarrolladores a mejorar la comprensión de sus modelos de IA","fr":"Ce-pipeline-builder est un référentiel pour la méthode d''explications calibrées, aidant les développeurs à améliorer la compréhension de leurs modèles d''IA","de":"Ce-pipeline-builder ist ein Repository für das Verfahren der kalibrierten Erklärungen, das Entwicklern hilft, das Verständnis ihrer KI-Modelle zu verbessern","pt":"O ce-pipeline-builder é um agente de IA especializado que implementa o método Calibrated Explanations (CE) para gerar documentação técnica automatizada e explicações para pipelines de CI/CD. Ele analisa código-fonte e configurações para produzir relatórios explicativos calibrados para desenvolved...","ru":"ce-pipeline-builder — это специализированный ИИ агент, реализующий метод Calibrated Explanations (CE) для генерации автоматизированной технической документации и объяснений для CI/CD пайплайнов. Он анализирует исходный код и конфигурации для создания калиброванных объяснительных о