INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('resend/react-email/react-email', 'react-email', 'resend', 'react-email', 'community', 'react-email resend react-email community React 电子邮件是一个现代的、基于组件的电子邮件开发方法，使用 React 组件构建和发送 HTML 电子邮件 React 電子メールは、React コンポーネントを使用して HTML 電子メールをビルドして送信する、モダンなコンポーネントベースの電子メール開発方法です React 이메일은 React 컴포넌트를 사용하여 HTML 이메일을 빌드하고 전송하는 모던한 컴포넌트 기반의 이메일 개발 방법입니다 React Email es una herramienta para construir y enviar correos electrónicos HTML utilizando componentes de React React Email est un outil pour créer et envoyer des emails HTML en utilisant des composants React React Email ist ein Tool zum Erstellen und Senden von HTML-E-Mails mithilfe von React-Komponenten O React Email é uma abordagem moderna e baseada em componentes para o desenvolvimento de e-mails que funciona em todos os principais clientes de e-mail React Email - это современный, компонентно-ориентированный подход к разработке электронных писем, который работает во всех основных клиентах электронной почты React Email هو نهج حديث وقائم على المكونات لتنمية البريد الإلكتروني والذي يعمل على جميع عملاء البريد الإلكتروني الرئيسيين 💌 Build and send emails using React React 电子邮件 React 邮件 电子邮件开发 React 组件 HTML 电子邮件 create-email CLI npm yarn pnpm bun 💌 Build and send emails using React');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mrexodia/ida-pro-mcp/idapython', 'community', 'mrexodia', 'ida-pro-mcp', 'mrexodia/ida-pro-mcp', 'idapython', 0, 0, 39, '2026-03-04T13:07:01.672Z', '2026-03-04T13:23:00.631Z', '421e209611d04299458034e03d9ff214d443f5bfef0403f3ffbebf35c79c61b1', '{"id":"mrexodia/ida-pro-mcp/idapython","name":"idapython","description":{"zh":"idapython是AI驱动的逆向工程助手，通过MCP连接IDA Pro与语言模型","ja":"idapythonはAI駆動の逆向工学アシスタントで、MCPを介してIDA Proと言語モデルを接続","ko":"idapython은 AI 기반 역공학 보조도구로, MCP를 통해 IDA Pro와 언어 모델을 연결","es":"idapython es un asistente de ingeniería inversa impulsado por IA que conecta IDA Pro con modelos de lenguaje a través de MCP, mejorando la eficiencia y la precisión en el análisis de código","fr":"idapython est un assistant d''ingénierie inverse alimenté par l''IA qui relie IDA Pro aux modèles de langage via MCP, améliorant l''efficacité et la précision dans l''analyse de code","de":"idapython ist ein Reverse-Engineering-Assistent mit KI-Unterstützung, der IDA Pro mit Sprachmodellen über MCP verbindet, um die Effizienz und Genauigkeit bei der Code-Analyse zu verbessern","pt":"O idapython é um assistente de engenharia reversa impulsionado por IA que conecta IDA Pro com modelos de linguagem via MCP, facilitando a análise de código.","ru":"Idapython - это ИИ-помощник реверсивной инженерии, который объединяет IDA Pro с языковыми моделями через MCP, упрощая анализ кода.","ar":"يعد idapython مساعد هندسة عكسية مدعوم بالذكاء الاصطناعي الذي يربط IDA Pro بنماذج اللغة من خلال MCP، مما يسهل تحليل الكود.","en":"AI-powered reverse engineering assistant that bridges IDA Pro with language models through MCP."},"seo":{"title":{"zh":"AI智能代理idapython：IDA Pro逆向工程助手","ja":"AIエージェントidapython：IDA Pro逆向工学アシスタント","ko":"AI 에이전트 idapython: IDA Pro 역공학 보조도구","es":"Asistente de ingeniería inversa con idapython y AI","fr":"Assistant d''ingénierie inver