INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mrexodia/ida-pro-mcp/idapython', 'idapython', 'mrexodia', 'ida-pro-mcp', 'community', 'idapython mrexodia ida-pro-mcp community idapython是AI驱动的逆向工程助手，通过MCP连接IDA Pro与语言模型 idapythonはAI駆動の逆向工学アシスタントで、MCPを介してIDA Proと言語モデルを接続 idapython은 AI 기반 역공학 보조도구로, MCP를 통해 IDA Pro와 언어 모델을 연결 idapython es un asistente de ingeniería inversa impulsado por IA que conecta IDA Pro con modelos de lenguaje a través de MCP, mejorando la eficiencia y la precisión en el análisis de código idapython est un assistant d''ingénierie inverse alimenté par l''IA qui relie IDA Pro aux modèles de langage via MCP, améliorant l''efficacité et la précision dans l''analyse de code idapython ist ein Reverse-Engineering-Assistent mit KI-Unterstützung, der IDA Pro mit Sprachmodellen über MCP verbindet, um die Effizienz und Genauigkeit bei der Code-Analyse zu verbessern O idapython é um assistente de engenharia reversa impulsionado por IA que conecta IDA Pro com modelos de linguagem via MCP, facilitando a análise de código. Idapython - это ИИ-помощник реверсивной инженерии, который объединяет IDA Pro с языковыми моделями через MCP, упрощая анализ кода. يعد idapython مساعد هندسة عكسية مدعوم بالذكاء الاصطناعي الذي يربط IDA Pro بنماذج اللغة من خلال MCP، مما يسهل تحليل الكود. AI-powered reverse engineering assistant that bridges IDA Pro with language models through MCP. idapython IDA Pro AI智能代理 逆向工程 MCP 语言模型 如何使用idapython idapython安装 idapython教程 AI-powered reverse engineering assistant that bridges IDA Pro with language models through MCP.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macro-inc/macro/qc', 'community', 'macro-inc', 'macro', 'macro-inc/macro', 'qc', 0, 0, 39, '2026-03-04T13:07:01.680Z', '2026-03-04T13:24:31.584Z', '422324a264f6f1a5578591e4174a9594747a6d20b2e532b6f88b4f9d250c888e', '{"id":"macro-inc/macro/qc","name":"qc","description":{"zh":"qc是集邮件、消息、任务、文档和文件于一体的AI智能工具，实现无缝连接和贡献报酬","ja":"qcは、メール、メッセージ、タスク、ドキュメント、ファイルを一つにまとめたAIエージェントで、貢献して報酬を得ることができる","ko":"qc는 이메일, 메시지, 태스크, 문서, 파일을 하나로 연결하는 AI 에이전트로 기여하고 보상을 받을 수 있습니다","es":"qc es un sistema integral para email, mensajería, tareas, docs y archivos. Permite a los usuarios contribuir y recibir recompensas.","fr":"qc est un système complet pour email, messagerie, tâches, docs et fichiers. Il permet aux utilisateurs de contribuer et de recevoir des récompenses.","de":"qc ist ein umfassendes System für E-Mail, Messaging, Aufgaben, Dokumente und Dateien. Es ermöglicht den Benutzern, beizutragen und Belohnungen zu erhalten.","pt":"O qc é um sistema integrado para email, mensagens, tarefas, docs e arquivos. Contribua e ganhe dinheiro com essa ferramenta de IA","ru":"ИИ Агент qc — это система для электронной почты, сообщений, задач, документов и файлов — все @linked. Получайте оплату за вклад","ar":"qc هو نظام متكامل للبريد الإلكتروني والرسائل والمهام والوثائق والملفات — جميعها متصلة. ساهم وكسب المال مع أداة الذكاء الاصطناعي هذه","en":"One system for email, messaging, tasks, docs, and files — all @linked. Get paid to contribute."},"seo":{"title":{"zh":"AI智能工具qc：集邮件、消息、任务、文档和文件于一体","ja":"AIエージェントqc：メール、メッセージ、タスク、ドキュメント、ファイルを一つにまとめたプラットフォーム","ko":"AI 에이전트 qc: 이메일, 메시지, 태스크, 문서, 파일을 하나로 연결","es":"Herramientas de Inteligencia Artificial: qc para email y ...","fr":"Outils d''Intelligence Artificielle: qc pour email et tâches","de":"KI-Tools: qc für E-Mail und Aufgaben","pt":"Ferramentas de IA: qc para Desenvolvedores","ru":"ИИ Агенты: qc для Разработчиков","ar":"أدوات الذكاء الاصطناعي: qc لل مطورين","en":"qc"},"description":{"zh":"qc是集邮件、消息、任务、文档和文件于一体的AI智能工具，实现无缝连接和贡献报酬","ja":"qcは、メール、メッセージ、タスク、ドキュメント、ファイルを一つにまとめたAIエージェントで、貢献して報酬を得ることができる","ko":"qc는 이메일, 메시지, 태스크, 문서, 파일을 하나로 연결하는 AI 에이전트로 기여하고 보상을 받을 수 있습니다","es":"qc es un sistema integral para email, mensajería, tareas, docs y archivos. Permite a los usuarios contribuir y recibir recompensas.","fr":"qc est un système complet pour email, messagerie, tâches, docs et fichiers. Il permet aux utilisateurs de contribuer et de recevoir des récompenses.","de":"qc ist ein umfassendes System für E-Mail, Messaging, Aufgaben, Dokumente und Dateien. Es ermöglicht den Benutzern, beizutragen und Belohnungen zu erhalten.","pt":"O qc é um sistema integrado para email, mensagens, tarefas, docs e arquivos. Contribua e ganhe dinheiro com essa ferramenta de IA","ru":"ИИ Агент qc — это система для электронной почты, сообщений, задач, документов и файлов — все @linked. Получайте оплату за вклад","ar":"qc هو نظام متكامل للبريد الإلكتروني والرسائل والمهام والوثائق والملفات — جميعها متصلة. ساهم وكسب المال مع أداة الذكاء الاصطناعي هذه","en":"One system for email, messaging, tasks, docs, and files — all @linked. Get paid to contribute."},"definition":{"en":"One system for email, messaging, tasks, docs, and files — all @linked. Get paid to contribute."},"features":{"zh":["集邮件、消息、任务、文档和文件于一体","实现无缝连接和贡献报酬","支持多种文件格式","提供安全可靠的数据存储","易于使用和安装"],"ja":["メール、メッセージ、タスク、ドキュメント、ファイルを一つにまとめる","貢献して報酬を得ることができる","多種のファイル形式をサポート","安全で信頼性の高いデータストレージを提供","簡単に使用してインストールできる"],"ko":["이메일, 메시지, 태스크, 문서, 파일을 하나로 연결","기여하고 보상을 받을 수 있습니다","다양한 파일 형식을 지원","安全하고 신뢰할 수 있는 데이터 저장소를 제공","쉽게 사용하고 설치할 수 있음"],"es":["Sistema todo en uno para email y tareas","Integración de mensajería y docs","Almacenamiento de archivos seguro","Opción de recibir recompensas por contribuir","Interfaz de usuario intuitiva"],"fr":["Système tout en un pour email et tâches","Intégration de la messagerie et des docs","Stockage de fichiers sécurisé","Option de recevoir des récompenses pour contribuer","Interface utilisateur intuitive"],"de":["All-in-One-System für E-Mail und Aufgaben","Integration von Messaging und Dokumenten","Sicheres Dateispeicherung","Option, Belohnungen für Beiträge zu erhalten","Benutzerfreundliche Oberfläche"],"pt":["Integração de email e mensagens","Gerenciamento de tarefas e docs","Armazenamento de arquivos","Contribuição e pagamento","Tecnologia de IA para desenvolvedores"],"ru":["Интеграция электронной почты и сообщений","Управление задачами и документами","Хранение файлов","Вклад и оплата","Технология ИИ для разработчиков"],"ar":["دمج البريد الإلكتروني والرسائل","إدارة المهام والوثائق","تخزين الملفات","المساهمة والدفع","تكنولوجيا الذكاء الاصطناعي للمطورين"]},"keywords":{"zh":["AI智能工具","qc工具","邮件管理","消息管理","任务管理","文档管理","文件管理","贡献报酬","如何使用qc","qc安装指南"],"ja":["AIエージェント","qcツール","メール管理","メッセージ管理","タスク管理","ドキュメント管理","ファイル管理","貢献報酬","qcの使い方","qcのインストールガイド"],"ko":["AI 에이전트","qc 툴","이메일 관리","메시지 관리","태스크 관리","문서 관리","파일 관리","기여 보상","qc 사용법","qc 설치 가이드"],"es":["cómo usar qc","qc alternativa","qc vs otras herramientas","instalación de qc","guía de configuración de qc","herramientas de Inteligencia Artificial para email","qc para desarrolladores","qc para programadores"],"fr":["comment utiliser qc","alternative à qc","qc vs autres outils","installation de qc","guide de configuration de qc","outils d''Intelligence Artificielle pour email","qc pour développeurs","qc pour programmeurs"],"de":["wie man qc verwendet","Alternative zu qc","qc vs andere Tools","Installation von qc","Konfigurationsanleitung für qc","KI-Tools für E-Mail","qc für Entwickler","qc für Programmierer"],"pt":["ferramentas de ia","qc para desenvolvedores","como usar qc","o que é qc","qc vs outros ferramentas","instalar qc","configurar qc"],"ru":["ИИ агенты","qc для разработчиков","как использовать qc","что такое qc","qc vs другие инструменты","установить qc","настроить qc"],"ar":["أدوات الذكاء الاصطناعي","qc للمطورين","كيفية استخدام qc","ما هو qc","qc مقابل أدوات أخرى","تثبيت qc","إعداد qc"]}},"owner":"macro-inc","repo":"macro","repoPath":"macro-inc/macro","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.680Z","topics":[],"category":"community","skillMd":{"name":"qc","description":"Quality gate. 5 parallel agents review changes. All must pass.","bodyPreview":"# QC Gate\n\n## Setup\n```bash\nDIFF=$(git diff main)\nFILES=$(git diff main --name-only)\nTASK=\"{task description or ''general changes''}\"\n```\n\nRead 1-2 unmodified files from same directories for pattern context.\n\n## Agents\n\nSpawn all 5 in parallel. All output raw JSON only, no markdown.\n\n### 1: Code Review (sonnet)\n```\nDIFF: ${DIFF}\n\n- Descriptive naming?\n- Errors caught with useful messages?\n- No hardcoded values, commented code, debug statements?\n- No TODO without ticket ref?\n- No obvious bugs?\n- No","body":"# QC Gate\n\n## Setup\n```bash\nDIFF=$(git diff main)\nFILES=$(git diff main --name-only)\nTASK=\"{task description or ''general changes''}\"\n```\n\nRead 1-2 unmodified files from same directories for pattern context.\n\n## Agents\n\nSpawn all 5 in parallel. All output raw JSON only, no markdown.\n\n### 1: Code Review (sonnet)\n```\nDIFF: ${DIFF}\n\n- Descriptive naming?\n- Errors caught with useful messages?\n- No hardcoded values, commented code, debug statements?\n- No TODO without ticket ref?\n- No obvious bugs?\n- No useless comments?\n\n{\"pass\": bool, \"issues\": [...]}\n```\n\n### 2: Simplification (sonnet)\n```\nDIFF: ${DIFF}\n\n- Is this overcomplicated? Can I solve the same problem in a simpler manner?\n- Can I reduce indirection?\n- Can I reduce surface area?\n- Premature abstraction? Premature Optimization? YAGNI violations?\n- Dead code?\n- Three similar lines > one abstraction\n\n{\"pass\": bool, \"issues\": [...]}\n```\n\n### 3: Consistency (sonnet)\n```\nDIFF: ${DIFF}\nPATTERNS: ${PATTERN_FILES}\n\n- Matches existing codebase patterns?\n- Proper types, no any, no unsafe casts?\n- Idiomatic error handling?\n- Changes internally consistent?\n- Is logic isolated and composable?\n- Are there existing tests if neccesary?\n\n{\"pass\": bool, \"issues\": [...]}\n```\n\n### 4: Robustness (sonnet)\n```\nTASK: ${TASK}\nDIFF: ${DIFF}\n\n- Actually solves the problem?\n- Edge cases: empty, null, zero, negative, boundaries, concurrency?\n- Regression risk: changed signatures, shared state, removed exports?\n- Maintains API contracts?\n\n{\"pass\": bool, \"issues\": [...]}\n```\n\n### 5: Scope (haiku)\n```\nTASK: ${TASK}\nFILES: ${FILES}\nDIFF: ${DIFF}\n\n- Solved the problem or just the symptom?\n- Changes unrelated to task?\n- Unnecessary refactoring?\n\n{\"pass\": bool, \"issues\": [...]}\n```\n\n## Results\n\n| Check | Verdict | Issues |\n|-------|---------|--------|\n| Code Review | ✓/✗ | ... |\n| Simplification | ✓/✗ | ... |\n| Consistency | ✓/✗ | ... |\n| Robustness | ✓/✗ | ... |\n| Scope | ✓/✗ | ... |\n\n**ALL PASS:** Ready to commit.\n\n**ANY FAIL:** List issues, fix them, run `/qc` again.\n\n**Same issue 3x:** Escalate to user.\n\n## Notes\n\n- Invalid JSON? Retry once. Still broken? Mark fail.\n- Large diffs (>500 lines): run simplification file-by-file.\n"},"lastSynced":"2026-03-04T13:24:31.584Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced git diff analysis and task management capabilities.","zh":"非常适合需要高级 git diff 分析和任务管理能力的代码审查代理。","ja":"コードレビュー代理に高度な git diff 分析とタスク管理機能が必要な場合に最適です。","ko":"고급 git diff 분석 및 작업 관리 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan un análisis avanzado de git diff y capacidades de gestión de tareas.","fr":"Parfait pour les agents de revue de code nécessitant une analyse avancée de git diff et des capacités de gestion de tâches.","de":"Perfekt für Code-Review-Agents, die eine erweiterte git diff-Analyse und Task-Management-Funktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de análise avançada de git diff e capacidades de gerenciamento de tarefas.","ru":"Идеально подходит для агентов кодового обзора, которым необходимы расширенный анализ git diff и возможности управления задачами.","ar":"مثالي لعمليات المراجعة البرمجية التي تحتاج إلى تحليل متقدم لgit diff وقدرات إدارة المهام."},"recommendation":{"en":"Empowers agents to analyze git diffs, detect errors, and enforce coding standards using git diff and JSON output, providing comprehensive content analysis and automated task description generation.","zh":"赋予代理分析 git 差异、检测错误并使用 git diff 和 JSON 输出执行编码标准，提供全面内容分析和自动任务描述生成。","ja":"エージェントが git の差分を分析し、エラーを検出して git diff と JSON 出力を使用してコーディング規約を強制し、包括的なコンテンツ分析と自動タスク記述の生成を提供します。","ko":"에이전트가 git의 차이를 분석하고, 오류를 감지하며 git diff 및 JSON 출력을 사용하여 코딩 표준을 적용하고, 종합적인 내용 분석 및 자동 작업 설명 생성을 제공합니다.","es":"Habilita a los agentes a analizar git diffs, detectar errores y aplicar normas de codificación utilizando git diff y salida JSON, proporcionando un análisis de contenido integral y generación automática de descripciones de tareas.","fr":"Permet aux agents d''analyser les git diffs, de détecter les erreurs et d''appliquer les normes de codage en utilisant git diff et la sortie JSON, offrant une analyse de contenu complète et une génération automatique de descriptions de tâches.","de":"Ermächtigt die Agenten, git diffs zu analysieren, Fehler zu erkennen und Codierungsstandards mithilfe von git diff und JSON-Ausgabe durchzusetzen, um eine umfassende Inhaltsanalyse und automatische Aufgabenbeschreibungsgenerierung bereitzustellen.","pt":"Habilita os agentes a analisar git diffs, detectar erros e impor padrões de codificação usando git diff e saída JSON, fornecendo análise abrangente de conteúdo e geração automática de descrições de tarefas.","ru":"Наделяет агентов возможностью анализировать git diffs, обнаруживать ошибки и обеспечивать соблюдение стандартов кодирования с помощью git diff и вывода JSON, обеспечивая всесторонний анализ содержания и автоматическую генерацию описаний задач.","ar":"يمنح الوكلاء القدرة على تحليل git diffs والكشف عن الأخطاء وفرض معايير الترميز باستخدام git diff و JSON الإخراج ، مع تقديم تحليل محتوى شامل وتوليد وصف المهام آليا."},"useCases":{"en":["Automating code reviews with git diff analysis","Generating task descriptions from code changes","Debugging code errors with useful error messages"],"zh":["使用 git diff 分析自动执行代码审查","从代码更改生成任务描述","使用有用的错误消息调试代码错误"],"ja":["git diff 分析によるコードレビューの自動化","コード変更からタスク記述の生成","有用なエラーメッセージによるコードエラーのデバッグ"],"ko":["git diff 분석을 통한 코드 리뷰 자동화","코드 변경에서 작업 설명 생성","유용한 오류 메시지를 통한 코드 오류 디버깅"],"es":["Automatización de revisiones de código con análisis de git diff","Generación de descripciones de tareas a partir de cambios de código","Depuración de errores de código con mensajes de error útiles"],"fr":["Automatisation des revues de code avec analyse de git diff","Génération de descriptions de tâches à partir de modifications de code","Débogage des erreurs de code avec des messages d''erreur utiles"],"de":["Automatisierung von Code-Reviews mit git diff-Analyse","Generierung von Aufgabenbeschreibungen aus Code-Änderungen","Fehlerbehebung mit nützlichen Fehlermeldungen"],"pt":["Automatizar revisões de código com análise de git diff","Gerar descrições de tarefas a partir de alterações de código","Depurar erros de código com mensagens de erro úteis"],"ru":["Автоматизация обзоров кода с помощью анализа git diff","Генерация описаний задач из изменений кода","Отладка ошибок кода с полезными сообщениями об ошибках"],"ar":["أتمتة استعراض الشفرة البرمجية مع تحليل git diff ","توليد وصف المهام من تغييرات الشفرة","تصحيح أخطاء الشفرة مع رسائل الخطأ المفيدة"]},"limitations":{"en":["Requires git installation and configuration","Limited to git diff analysis, no support for other version control systems"],"zh":["需要 git 安装和配置","仅限 git diff 分析，不支持其他版本控制系统"],"ja":["git のインストールと設定が必要","git diff 分析のみに限定され、他のバージョン管理システムはサポートされません"],"ko":["git 설치 및 구성이 필요","git diff 분석만 제한되어 다른 버전 관리 시스템은 지원되지 않음"],"es":["Requiere instalación y configuración de git","Limitado al análisis de git diff, sin soporte para otros sistemas de control de versiones"],"fr":["Nécessite l''installation et la configuration de git","Limité à l''analyse de git diff, sans prise en charge d''autres systèmes de contrôle de version"],"de":["Benötigt die Installation und Konfiguration von git","Begrenzt auf die Analyse von git diff, ohne Unterstützung für andere Versionskontrollsysteme"],"pt":["Exige instalação e configuração do git","Limitado à análise de git diff, sem suporte para outros sistemas de controle de versão"],"ru":["Требует установки и настройки git","Ограничен анализом git diff, без поддержки других систем контроля версий"],"ar":["يتطلب تثبيت وتكوين git ","محدود بتحليل git diff ، بدون دعم لأنظمة التحكم في الإصدارات الأخرى"]},"version":3},"contentHash":"422324a264f6f1a5578591e4174a9594747a6d20b2e532b6f88b4f9d250c888e","qualityScore":39}');
