INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wrsmith108/governance-claude-skill/governance', 'governance', 'wrsmith108', 'governance-claude-skill', 'community', 'governance wrsmith108 governance-claude-skill community Claude Code 的 AI 智能代理技能用于工程标准和代码治理，确保代码质量和开发效率 Claude Code の AI エージェントスキルはエンジニアリングスタンダードとコードガバナンスを実施する Claude Code의 AI 에이전트 스킬은 엔지니어링 표준 및 코드 거버넌스를 적용합니다 Claude Code es una habilidad para la gobernanza de código y el cumplimiento de los estándares de ingeniería para Agentes de IA Claude Code est une compétence pour la gouvernance du code et le respect des normes d''ingénierie pour les Agents IA Claude Code ist eine Fähigkeit für die Code-Governance und die Einhaltung der Ingenieurnormen für KI-Agenten Claude Code é uma habilidade de governança de código para engenharia que ajuda a manter padrões de código Claude Code - навык управления кодом для инженерии, помогающий поддерживать стандарты кода Claude Code هو مهارة حوكمة شيفرة للهندسة تساعد على الحفاظ على معايير الشيفرة Claude Code skill for engineering standards and code governance enforcement AI智能代理 代码管理 代码治理 工程标准 代码质量 开发效率 代码安全 代码版本控制 如何使用AI智能代理 AI智能代理安装指南 Claude Code skill for engineering standards and code governance enforcement');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ksoichiro/ChronoDawn/doc-maintenance', 'community', 'ksoichiro', 'ChronoDawn', 'ksoichiro/ChronoDawn', 'doc-maintenance', 0, 0, 39, '2026-03-04T13:07:01.765Z', '2026-03-04T14:16:55.260Z', 'dbe8e117d7887acb86f2b81d30de994a1732f20327b271d7073704bbf243668c', '{"id":"ksoichiro/ChronoDawn/doc-maintenance","name":"doc-maintenance","description":{"zh":"doc-maintenance是一个Minecraft时间维度模组，添加了Chrono Dawn时间主题世界，支持Fabric和NeoForge","ja":"doc-maintenanceはMinecraftの時間テーマワールドを追加するモッドで、FabricとNeoForgeをサポート","ko":"doc-maintenance는 마인크래프트 시간 차원 모드로서 Chrono Dawn 시간 테마 월드를 추가하며 Fabric와 NeoForge를 지원","es":"Doc-maintenance es una herramienta de IA para Minecraft que agrega un mundo de tiempo con portales personalizados y batallas de jefes","fr":"Doc-maintenance est un outil d''IA pour Minecraft qui ajoute un monde de temps avec des portails personnalisés et des batailles de boss","de":"Doc-maintenance ist ein KI-Tool für Minecraft, das eine Zeitwelt mit benutzerdefinierten Portalen und Bosskämpfen hinzufügt","pt":"O mod doc-maintenance adiciona um mundo temático de tempo ao Minecraft com portais personalizados e artefatos de manipulação do tempo","ru":"Мод doc-maintenance добавляет время-тематический мир в Minecraft с кастомными порталами и артефактами манипуляции временем","ar":"يضيف مود doc-maintenance عالمًا محوريًا للزمن إلى مايﾝكرافت مع بوابات مخصصة وتحف من يمانيبولات الوقت","en":"🕰️ A dimension mod for Minecraft that adds Chrono Dawn, a time-themed world with custom portals, boss battles, and time-manipulating artifacts. Supports Fabric & NeoForge."},"seo":{"title":{"zh":"AI智能代理doc-maintenance：Minecraft时间维度模组","ja":"AIエージェントdoc-maintenance：Minecraftの時間テーマワールド","ko":"AI 에이전트 doc-maintenance: 마인크래프트 시간 차원 모드","es":"Herramientas de IA: doc-maintenance para Minecraft","fr":"Outils d''IA: doc-maintenance pour Minecraft","de":"KI-Tools: doc-maintenance für Minecraft","pt":"Ferramentas de IA: doc-maintenance para Minecraft","ru":"ИИ Агенты: doc-maintenance для Minecraft","ar":"أدوات الذكاء الاصطناعي: doc-maintenance لمايﾝكرافت","en":"doc-maintenance"},"description":{"zh":"doc-maintenance是一个Minecraft时间维度模组，添加了Chrono Dawn时间主题世界，支持Fabric和NeoForge","ja":"doc-maintenanceはMinecraftの時間テーマワールドを追加するモッドで、FabricとNeoForgeをサポート","ko":"doc-maintenance는 마인크래프트 시간 차원 모드로서 Chrono Dawn 시간 테마 월드를 추가하며 Fabric와 NeoForge를 지원","es":"Doc-maintenance es una herramienta de IA para Minecraft que agrega un mundo de tiempo con portales personalizados y batallas de jefes","fr":"Doc-maintenance est un outil d''IA pour Minecraft qui ajoute un monde de temps avec des portails personnalisés et des batailles de boss","de":"Doc-maintenance ist ein KI-Tool für Minecraft, das eine Zeitwelt mit benutzerdefinierten Portalen und Bosskämpfen hinzufügt","pt":"O mod doc-maintenance adiciona um mundo temático de tempo ao Minecraft com portais personalizados e artefatos de manipulação do tempo","ru":"Мод doc-maintenance добавляет время-тематический мир в Minecraft с кастомными порталами и артефактами манипуляции временем","ar":"يضيف مود doc-maintenance عالمًا محوريًا للزمن إلى مايﾝكرافت مع بوابات مخصصة وتحف من يمانيبولات الوقت","en":"🕰️ A dimension mod for Minecraft that adds Chrono Dawn, a time-themed world with custom portals, boss battles, and time-manipulating artifacts. Supports Fab..."},"definition":{"en":"🕰️ A dimension mod for Minecraft that adds Chrono Dawn, a time-themed world with custom portals, boss battles, and time-manipulating artifacts. Supports Fabric & NeoForge."},"features":{"zh":["自定义传送门","boss战","时间操纵神器","支持Fabric和NeoForge","时间主题世界","Chrono Dawn世界"],"ja":["カスタムポータル","ボスバトル","時間操作アーティファクト","FabricとNeoForgeのサポート","時間テーマワールド","Chrono Dawnワールド"],"ko":["커스텀 포털","보스 전투","시간 조작 아티팩트","Fabric와 NeoForge 지원","시간 테마 월드","Chrono Dawn 월드"],"es":["Mundo de tiempo con portales personalizados","Batallas de jefes y artefactos que manipulan el tiempo","Compatibilidad con Fabric y NeoForge","Funcionalidades de tiempo personalizadas","Soporte para mods de Minecraft"],"fr":["Monde de temps avec des portails personnalisés","Batailles de boss et artefacts qui manipulent le temps","Compatibilité avec Fabric et NeoForge","Fonctionnalités de temps personnalisées","Prise en charge des mods de Minecraft"],"de":["Zeitwelt mit benutzerdefinierten Portalen","Bosskämpfe und Artefakte, die die Zeit manipulieren","Kompatibilität mit Fabric und NeoForge","Benutzerdefinierte Zeitfunktionen","Unterstützung für Minecraft-Mods"],"pt":["Mundo temático de tempo","Portais personalizados","Batalhas com chefes","Artefatos de manipulação do tempo","Suporte a Fabric e NeoForge"],"ru":["Время-тематический мир","Кастомные порталы","Битвы с боссами","Артефакты манипуляции временем","Поддержка Fabric и NeoForge"],"ar":["عالم محوري للزمن","بوابات مخصصة","معارك مع الرؤساء","تحف من يمانيبولات الوقت","دعم Fabric و NeoForge"]},"keywords":{"zh":["Minecraft模组","时间主题世界","时间操纵","Fabric模组","NeoForge模组","如何安装doc-maintenance","doc-maintenance教程","Minecraft时间维度模组","AI智能代理"],"ja":["Minecraftモッド","時間テーマワールド","時間操作","Fabricモッド","NeoForgeモッド","doc-maintenanceのインストール方法","doc-maintenanceチュートリアル","Minecraft時間テーマワールド","AIエージェント"],"ko":["마인크래프트 모드","시간 테마 월드","시간 조작","Fabric 모드","NeoForge 모드","doc-maintenance 설치 방법","doc-maintenance 튜토리얼","마인크래프트 시간 테마 월드","AI 에이전트"],"es":["herramientas de ia para minecraft","doc-maintenance","mundo de tiempo en minecraft","cómo instalar doc-maintenance","mejores mods de minecraft","alternativas a doc-maintenance","guias de configuración de doc-maintenance","configuración de doc-maintenance","descargar doc-maintenance"],"fr":["outils d''ia pour minecraft","doc-maintenance","monde de temps sur minecraft","comment installer doc-maintenance","meilleurs mods de minecraft","alternatives à doc-maintenance","guides de configuration de doc-maintenance","configuration de doc-maintenance","télécharger doc-maintenance"],"de":["ki-tools für minecraft","doc-maintenance","zeitwelt in minecraft","wie installiere ich doc-maintenance","beste minecraft-mods","alternativen zu doc-maintenance","anleitungen zur konfiguration von doc-maintenance","konfiguration von doc-maintenance","doc-maintenance herunterladen"],"pt":["como usar doc-maintenance","o que é doc-maintenance","alternativa para doc-maintenance","doc-maintenance vs outros mods","instalar doc-maintenance","guia de configuração do doc-maintenance"],"ru":["как использовать doc-maintenance","что такое doc-maintenance","альтернатива doc-maintenance","doc-maintenance vs другие моды","установить doc-maintenance","гид по настройке doc-maintenance"],"ar":["كيفية استخدام doc-maintenance","ما هو doc-maintenance","بديل ل doc-maintenance","doc-maintenance مقابل mods أخرى","تثبيت doc-maintenance","دليل إعداد doc-maintenance"]}},"owner":"ksoichiro","repo":"ChronoDawn","repoPath":"ksoichiro/ChronoDawn","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.765Z","topics":[],"category":"community","skillMd":{"name":"doc-maintenance","description":"Guide documentation updates when changing versions, adding content, or preparing releases","bodyPreview":"# Documentation Maintenance\n\n**Purpose**: Guide documentation updates when changing versions, adding content, or preparing releases.\n\n**How it works**: This skill is automatically activated when you mention tasks related to:\n- Updating Minecraft or dependency versions\n- Adding new bosses, structures, or items\n- Preparing for a release\n- Adding new mod dependencies\n\nSimply describe what you want to do, and Claude will reference the appropriate checklist from this skill.\n\n---\n\n## Version Update Ch","body":"# Documentation Maintenance\n\n**Purpose**: Guide documentation updates when changing versions, adding content, or preparing releases.\n\n**How it works**: This skill is automatically activated when you mention tasks related to:\n- Updating Minecraft or dependency versions\n- Adding new bosses, structures, or items\n- Preparing for a release\n- Adding new mod dependencies\n\nSimply describe what you want to do, and Claude will reference the appropriate checklist from this skill.\n\n---\n\n## Version Update Checklist\n\n**When to use**: Updating Minecraft version, mod loader versions, or dependency versions\n\n### Files to Update\n\n1. **gradle.properties**\n   - Update version properties\n   - Example: `minecraft_version=1.21.1`\n\n2. **README.md** (lines ~47-50)\n   - Section: \"Requirements\" → \"Dependencies\"\n   - Update all version numbers\n\n3. **docs/player_guide.md** (lines ~25-56)\n   - Sections: \"Prerequisites\" and \"Required Dependencies\"\n   - Update version numbers and download links\n\n4. **docs/developer_guide.md** (lines ~32-45)\n   - Section: \"Key Technologies\"\n   - Update version specifications\n\n5. **docs/curseforge_description.md** (lines ~125-128)\n   - Section: \"Technical Details\" → \"Requirements\" → \"Dependencies\"\n   - Update version numbers\n\n6. **docs/modrinth_description.md** (lines ~30-39)\n   - Sections: \"Requirements\" (both Fabric and NeoForge)\n   - Update version numbers\n\n7. **fabric/src/main/resources/fabric.mod.json**\n   - Update `depends` section version ranges\n   - Update `recommends` section if applicable\n\n8. **neoforge/src/main/resources/META-INF/neoforge.mods.toml**\n   - Update `[[dependencies.chronodawn]]` entries\n   - Update `versionRange` fields\n\n9. **THIRD_PARTY_LICENSES.md**\n   - Update version numbers in \"Runtime Dependencies\" section\n   - Update: Minecraft, Fabric Loader, Fabric API, NeoForge, Architectury API\n   - Update \"Last updated\" date at the bottom\n\n### Current Versions (Reference)\n\n```\nMinecraft: 1.21.1\nFabric Loader: 0.17.3+\nFabric API: 0.116.7+\nNeoForge: 21.1.209+\nArchitectury API: 13.0.8+\n```\n\n**After updating**, update this reference list in this skill file.\n\n---\n\n## Adding a New Boss\n\n**When to use**: Adding a new boss enemy to the mod\n\n### Files to Update\n\n1. **README.md** (lines ~25-31)\n   - Section: \"Boss Enemies\" list\n   - Add: `- Boss Name (description, drops Item Name)`\n\n2. **docs/player_guide.md**\n   - Section: \"Boss Battles\"\n   - Add full entry with:\n     - Stats (Health, Attack, Defense)\n     - Abilities (list special attacks)\n     - Strategy (combat tips)\n     - Drops (items dropped)\n\n3. **docs/curseforge_description.md** (lines ~28-35)\n   - Section: \"Powerful Boss Battles\"\n   - Add boss to appropriate category (mini-boss, mid-boss, final boss)\n\n4. **docs/modrinth_description.md** (lines ~105-140)\n   - Section: \"Boss Battles\"\n   - Add boss entry with stats and abilities\n\n5. **specs/chrono-dawn-mod/spec.md**\n   - Add to User Stories if boss is critical to progression\n   - Add to Requirements section\n\n6. **specs/chrono-dawn-mod/data-model.md**\n   - Add boss entity definition with complete specifications\n\n7. **specs/chrono-dawn-mod/tasks.md**\n   - Add implementation tasks for the boss\n\n### Template\n\n```markdown\n### Boss Name (Category)\n\n**Location**: Structure Name\n\n**Stats**:\n- Health: XXX HP\n- Attack: XX damage\n- Defense: XX armor points\n\n**Abilities**:\n- Ability 1: Description\n- Ability 2: Description\n\n**Strategy**:\n- Tip 1\n- Tip 2\n\n**Drops**:\n- **Item Name**: Description\n- Experience points\n```\n\n---\n\n## Adding a New Structure\n\n**When to use**: Adding a new structure to the mod\n\n### Files to Update\n\n1. **README.md** (lines ~17-24)\n   - Section: \"Major Structures\" list\n   - Add: `- Structure Name (location, description)`\n\n2. **docs/player_guide.md**\n   - Section: \"Exploring the Chrono Dawn\" or appropriate section\n   - Add structure description and how to find it\n\n3. **docs/curseforge_description.md** (lines ~22-29)\n   - Section: \"Epic Structures\"\n   - Add structure to the list\n\n4. **docs/modrinth_description.md** (lines ~89-97)\n   - Section: \"Structures\"\n   - Add structure entry\n\n5. **specs/chrono-dawn-mod/spec.md**\n   - Add to User Stories if structure is critical\n   - Add to Requirements if needed\n\n6. **specs/chrono-dawn-mod/data-model.md**\n   - Add structure definition (generation rules, loot, etc.)\n\n---\n\n## Adding a New Ultimate Artifact\n\n**When to use**: Adding a new ultimate artifact item\n\n### Files to Update\n\n1. **README.md** (line ~32)\n   - Section: \"Ultimate Artifacts\" list\n   - Add: `Item Name (type), Description`\n\n2. **docs/player_guide.md**\n   - Section: \"Ultimate Artifacts\"\n   - Add full entry with:\n     - Stats (damage, armor, durability)\n     - Special Ability (detailed description)\n     - Recipe (crafting requirements)\n\n3. **docs/curseforge_description.md** (lines ~41-46)\n   - Section: \"Ultimate Artifacts\"\n   - Add brief description\n\n4. **docs/modrinth_description.md** (lines ~143-167)\n   - Section: \"Ultimate Artifacts\"\n   - Add item entry with ability description\n\n5. **specs/chrono-dawn-mod/data-model.md**\n   - Add item definition with complete specifications\n\n### Template\n\n```markdown\n### Item Name (Type)\n\n**Stats**:\n- Stat 1: Value\n- Stat 2: Value\n\n**Special Ability**: **Ability Name**\n- Effect description\n- Usage notes\n\n**Recipe**:\n\\`\\`\\`\n- Ingredient 1\n- Ingredient 2\n- Ingredient 3\n\\`\\`\\`\n```\n\n---\n\n## Updating Content Counts and Lists\n\n**When to use**: Adding or removing biomes, bosses, structures, wood types, or other countable content\n\n**Purpose**: Ensure numeric descriptions (e.g., \"8 unique biomes\", \"4 mid-bosses\", \"three wood types\") remain accurate across all documentation\n\n### Files to Check\n\n1. **README.md**\n   - Check: Biome count, boss count, structure count, wood type count\n   - Look for: \"8 unique biomes\", \"Boss Enemies\" list length, \"Major Structures\" list length\n\n2. **docs/player_guide.md**\n   - Check: Biome count, boss count (categorized: mini-boss, mid-bosses, final boss), structure count, wood type count\n   - Look for: \"8 unique biomes\", \"three wood types\", mid-boss descriptions (\"4 mid-bosses\")\n\n3. **docs/curseforge_description.md**\n   - Check: Biome count, boss count, structure count, artifact count\n   - Look for: \"8 Unique Biomes\", boss list lengths, structure list\n\n4. **docs/modrinth_description.md**\n   - Check: Biome count, boss count, structure count, wood type count\n   - Look for: \"8 unique biomes\", boss list, structure list\n\n5. **CLAUDE.md**\n   - Check: Current versions list if content affects version compatibility\n   - Look for: \"8 unique biomes\" in Recent Changes or Active Technologies\n\n### Verification Method\n\nWhen adding/removing content:\n1. Search for numeric descriptions (e.g., \"8\", \"four\", \"4 mid-bosses\")\n2. Verify counts match actual implementation\n3. Update Table of Contents if section counts change\n4. Check for phrases like \"all X\", \"both\", \"each of the Y\"\n\n**Tip**: Use `grep -r \"8 unique biomes\" docs/` to find all occurrences quickly\n\n---\n\n## Adding a New Dependency\n\n**When to use**: Adding a new mod dependency (required or optional)\n\n### Files to Update\n\n1. **gradle.properties**\n   - Add version property if needed\n   - Example: `new_mod_version=1.0.0`\n\n2. **fabric/build.gradle**\n   - Add to `dependencies` section\n   - Use `modImplementation`, `modApi`, or `modCompileOnly` as appropriate\n\n3. **neoforge/build.gradle**\n   - Add to `dependencies` section\n   - Use `modImplementation`, `modApi`, or `modCompileOnly` as appropriate\n\n4. **fabric/src/main/resources/fabric.mod.json**\n   - Add to `depends` (required) or `recommends` (optional)\n   - Specify version range\n\n5. **neoforge/src/main/resources/META-INF/neoforge.mods.toml**\n   - Add `[[dependencies.chronodawn]]` entry\n   - Set `type` to \"required\" or \"optional\"\n   - Specify `versionRange`\n\n6. **README.md** (lines ~47-50)\n   - Section: \"Requirements\" → \"Dependencies\"\n   - Add dependency with version and description\n\n7. **docs/player_guide.md** (lines ~41-56)\n   - Section: \"Required Dependencies\"\n   - Add numbered entry with links to CurseForge and Modrinth\n\n8. **docs/curseforge_description.md** (lines ~125-128)\n   - Section: \"Requirements\" → \"Dependencies\"\n   - Add dependency to the list\n\n9. **docs/modrinth_description.md** (lines ~30-39)\n   - Sections: \"Requirements\" (both Fabric and NeoForge)\n   - Add dependency to both loader sections\n\n10. **THIRD_PARTY_LICENSES.md**\n    - Add new dependency entry to \"Runtime Dependencies\" or \"Development Dependencies\" section\n    - Include: Project name, version, developer/organization, license, URL, license URL\n    - Add license summary if it''s a new license type\n    - Update \"Last updated\" date at the bottom\n    - Research license information from project''s GitHub repository or official page\n\n### Dependency Type Guidelines\n\n- **Required (`depends` / `required`)**: Mod cannot function without it\n- **Optional (`recommends` / `optional`)**: Adds features but not essential\n- **Include in JAR**: Use `include` in Fabric for bundling\n\n---\n\n## Pre-Release Verification\n\n**When to use**: Before creating a release or publishing to CurseForge/Modrinth\n\n### Checklist\n\n- [ ] **Version Consistency**\n  - All documentation files show consistent version numbers\n  - gradle.properties matches documentation\n  - fabric.mod.json and neoforge.mods.toml dependencies match gradle files\n\n- [ ] **Documentation Accuracy**\n  - README.md is accurate and up-to-date\n  - player_guide.md is complete with all features\n  - developer_guide.md reflects current architecture\n  - curseforge_description.md ready for publication\n  - modrinth_description.md ready for publication\n\n- [ ] **Configuration Files**\n  - fabric.mod.json has correct dependencies\n  - neoforge.mods.toml has correct dependencies\n  - All dependency versions are tested and working\n\n- [ ] **Build Verification**\n  - `./gradlew clean build` succeeds for both loaders\n  - JAR files are generated correctly\n  - No build warnings or errors\n\n- [ ] **Testing**\n  - All unit tests pass (`./gradlew test`)\n  - Manual testing completed (see quickstart.md checklist)\n  - Both Fabric and NeoForge builds tested in-game\n\n- [ ] **CHANGELOG** (if using)\n  - CHANGELOG.md exists and is current\n  - All user-facing changes documented\n\n- [ ] **GitHub Repository**\n  - All changes committed and pushed\n  - Branch is up-to-date with main/develop\n  - Tags are ready for release version\n\n---\n\n## Quick Reference\n\n### Documentation Files by Purpose\n\n**User-Facing**:\n- `README.md` - Project overview, installation, build instructions\n- `docs/player_guide.md` - Complete gameplay guide\n- `docs/curseforge_description.md` - CurseForge mod page content\n- `docs/modrinth_description.md` - Modrinth mod page content\n\n**Legal**:\n- `LICENSE` - Project license (MIT)\n- `THIRD_PARTY_LICENSES.md` - Dependency licenses and version information\n\n**Developer**:\n- `docs/developer_guide.md` - Development setup and architecture\n- `specs/chrono-dawn-mod/spec.md` - Feature specification\n- `specs/chrono-dawn-mod/data-model.md` - Data models\n- `specs/chrono-dawn-mod/tasks.md` - Implementation tasks\n\n**Configuration**:\n- `gradle.properties` - Version definitions\n- `fabric/src/main/resources/fabric.mod.json` - Fabric metadata\n- `neoforge/src/main/resources/META-INF/neoforge.mods.toml` - NeoForge metadata\n\n### Common Line Number References\n\n- README.md Dependencies: ~47-50\n- player_guide.md Prerequisites: ~25-56\n- developer_guide.md Technologies: ~32-45\n- curseforge_description.md Requirements: ~125-128\n- modrinth_description.md Requirements: ~30-39\n- README.md Boss List: ~25-31\n- README.md Structure List: ~17-24\n\n---\n\n## Tips\n\n1. **Always update in pairs**: When updating Fabric configs, update NeoForge configs too\n2. **Test both loaders**: Changes to dependencies affect both Fabric and NeoForge differently\n3. **Use search**: Use `grep` or IDE search to find all occurrences of version numbers\n4. **Keep CLAUDE.md current**: Update the current versions list after major updates\n5. **Commit frequently**: Commit documentation changes separately from code changes\n\n---\n\n**Last Updated**: 2025-12-08 (Added THIRD_PARTY_LICENSES.md to maintenance checklists)\n**Maintained by**: Chrono Dawn Development Team\n"},"lastSynced":"2026-03-04T14:16:55.260Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude, AutoGPT, and LangChain needing automated documentation updates for Minecraft mods, especially those with custom portals, boss battles, and time-manipulating artifacts.","zh":"非常适合像 Claude、AutoGPT 和 LangChain 这样的 AI Agent，它们需要为 Minecraft 模组（尤其是那些具有自定义门户、boss 战斗和时间操纵神器的模组）进行自动化文档更新。","ja":"Claude、AutoGPT、LangChain などの AI エージェントに最適で、Minecraft モッド（特にカスタムポータル、ボスバトル、時間操作アーティファクトを備えたもの）向けの自動ドキュメント更新が必要です。","ko":"Claude, AutoGPT, LangChain 같은 AI 에이전트에게 적합하며, 특히 사용자 정의 포털, 보스 전투 및 시간 조작 아티팩트가 있는 Minecraft 모드에 대한 자동화된 문서 업데이트가 필요합니다.","es":"Ideal para AI Agents como Claude, AutoGPT y LangChain que necesitan actualizaciones automatizadas de documentación para mods de Minecraft, especialmente aquellos con portales personalizados, batallas contra jefes y artefactos que manipulan el tiempo.","fr":"Parfait pour les AI Agents comme Claude, AutoGPT et LangChain nécessitant des mises à jour automatisées de la documentation pour les mods Minecraft, en particulier ceux avec des portails personnalisés, des combats de boss et des artefacts manipulant le temps.","de":"Perfekt für AI Agents wie Claude, AutoGPT und LangChain, die automatisierte Dokumentationsaktualisierungen für Minecraft-Mods benötigen, insbesondere für solche mit benutzerdefinierten Portalen, Bosskämpfen und zeitmanipulierenden Artefakten.","pt":"Perfeito para Agentes de IA como Claude, AutoGPT e LangChain que necessitam de atualizações automatizadas de documentação para mods do Minecraft, especialmente aqueles com portais personalizados, batalhas de chefes e artefatos que manipulam o tempo.","ru":"Идеально для агентов ИИ, таких как Claude, AutoGPT и LangChain, которым требуются автоматические обновления документации для модов Minecraft, особенно для тех, которые имеют пользовательские порталы, бои с боссами и артефакты, манипулирующие временем.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude و AutoGPT و LangChain الذين يحتاجون إلى تحديثات وثائق خود độngة لمودات Minecraft، especialmente تلك التي تحتوي على بوابات مخصصة ومعارك زعماء وأشياء تتحكم في الوقت."},"recommendation":{"en":"Empowers agents to manage and update documentation efficiently using checklists triggered by tasks such as updating Minecraft versions, adding new content, or preparing releases, all while supporting Fabric and NeoForge.","zh":"赋予代理管理和更新文档的能力，使用由任务触发的检查清单，例如更新 Minecraft 版本、添加新内容或准备发布，同时支持 Fabric 和 NeoForge。","ja":"エージェントがタスクによってトリガーされるチェックリストを使用して、ドキュメントを効率的に管理および更新できるようにします。たとえば、Minecraft バージョンの更新、ニュー コンテンツの追加、リリースの準備など、Fabric と NeoForge をサポートします。","ko":"에이전트가 Minecraft 버전 업데이트, 새로운 콘텐츠 추가 또는 릴리즈 준비와 같은 작업에 의해 트리거되는 체크리스트를 사용하여 문서를 효율적으로 관리하고 업데이트할 수 있도록 합니다. Fabric 및 NeoForge также 지원됩니다.","es":"Permite a los agentes gestionar y actualizar la documentación de manera eficiente utilizando listas de verificación activadas por tareas como la actualización de versiones de Minecraft, la adición de nuevo contenido o la preparación de lanzamientos, todo mientras admite Fabric y NeoForge.","fr":"Permet aux agents de gérer et de mettre à jour la documentation efficacement en utilisant des listes de contrôle déclenchées par des tâches telles que la mise à jour des versions de Minecraft, l''ajout de nouveau contenu ou la préparation des versions, le tout tout en prenant en charge Fabric et NeoForge.","de":"Ermöglicht Agents, die Dokumentation effizient mit Checklisten zu verwalten und zu aktualisieren, die durch Aufgaben wie das Aktualisieren von Minecraft-Versionen, das Hinzufügen neuer Inhalte oder das Vorbereiten von Releases ausgelöst werden, alles bei Unterstützung von Fabric und NeoForge.","pt":"Habilita os agentes a gerenciar e atualizar a documentação de forma eficiente usando listas de verificação acionadas por tarefas, como atualizar versões do Minecraft, adicionar novo conteúdo ou preparar lançamentos, tudo isso com suporte a Fabric e NeoForge.","ru":"Наделяет агентов возможностью эффективно управлять и обновлять документацию, используя чек-листы, запускаемые задачами, такими как обновление версий Minecraft, добавление нового контента или подготовка релизов, при этом поддерживая Fabric и NeoForge.","ar":"يمنح الوكيل القدرة على إدارة وتحديث الوثائق بفعالية باستخدام قوائم التحقق التي تتم بواسطة مهام مثل تحديث إصدارات Minecraft أو إضافة محتوى جديد أو إعداد الإصدارات، مع دعم Fabric و NeoForge."},"useCases":{"en":["Automating documentation updates for Minecraft mod version changes","Generating checklists for adding new bosses, structures, or items to the mod","Streamlining release preparations with comprehensive documentation checks"],"zh":["为 Minecraft 模组版本更改自动更新文档","为模组添加新 boss、结构或物品生成检查清单","使用全面的文档检查简化发布准备"],"ja":["Minecraft モッドのバージョン変更の自動ドキュメント更新","モッドに新しいボス、構造、またはアイテムを追加するためのチェックリストの生成","包括的なドキュメント チェックを使用したリリース準備の簡素化"],"ko":["Minecraft 모드 버전 변경에 대한 자동 문서 업데이트","모드에 새로운 보스, 구조 또는 아이템을 추가하기 위한 체크리스트 생성","포괄적인 문서 검사를 사용한 릴리스 준비 단순화"],"es":["Automatización de actualizaciones de documentación para cambios de versión de mods de Minecraft","Generación de listas de verificación para agregar nuevos jefes, estructuras o elementos al mod","Optimización de los preparativos de lanzamiento con comprobaciones exhaustivas de la documentación"],"fr":["Automatisation des mises à jour de la documentation pour les changements de version des mods Minecraft","Génération de listes de contrôle pour ajouter de nouveaux boss, structures ou objets au mod","Rationalisation des préparations de version avec des vérifications complètes de la documentation"],"de":["Automatisierung von Dokumentationsaktualisierungen für Minecraft-Mod-Versionsänderungen","Erstellung von Checklisten für das Hinzufügen neuer Bosse, Strukturen oder Gegenstände zum Mod","Straffung der Release-Vorbereitungen mit umfassenden Dokumentationsprüfungen"],"pt":["Automatizar atualizações de documentação para alterações de versão de mods do Minecraft","Gerar listas de verificação para adicionar novos chefes, estruturas ou itens ao mod","Otimitzar preparativos de lançamento com verificações de documentação abrangentes"],"ru":["Автоматизировать обновления документации для изменений версий модов Minecraft","Генерировать чек-листы для добавления новых боссов, структур или предметов в мод","Оптимизировать подготовку релизов с комплексными проверками документации"],"ar":["توفير تحديثات وثائق خود 动ة لتحديثات إصدار مودات Minecraft","توليد قوائم التحقق لإضافة زعماء أو هياكل أو عناصر جديدة إلى المود","تحسين إعدادات الإصدار مع عمليات فحص وثائق شاملة"]},"limitations":{"en":["Requires activation through specific task-related descriptions","Limited to documentation maintenance for Minecraft mods"],"zh":["需要通过特定任务相关描述激活","仅限于 Minecraft 模组的文档维护"],"ja":["特定タスク関連の説明を介してのアクティベーションが必要","Minecraft モッドのドキュメント メンテナンスに限定"],"ko":["특정 작업 관련 설명을 통해 활성화가 필요합니다","Minecraft 모드의 문서 유지 보수에만 제한됨"],"es":["Requiere activación a través de descripciones específicas relacionadas con tareas","Limitado al mantenimiento de documentación para mods de Minecraft"],"fr":["Nécessite une activation via des descriptions spécifiques liées aux tâches","Limité à la maintenance de la documentation pour les mods Minecraft"],"de":["Erfordert eine Aktivierung durch spezifische aufgabenbezogene Beschreibungen","Beschränkt sich auf die Dokumentationswartung für Minecraft-Mods"],"pt":["Requer ativação por meio de descrições de tarefas específicas","Limitado à manutenção de documentação para mods do Minecraft"],"ru":["Требует активации через конкретные описания задач","Ограничен только обслуживанием документации для модов Minecraft"],"ar":["يتطلب تنشيطًا من خلال وصفات مهمة محددة","محدود فقط بالصيانة لوثائق مودات Minecraft"]},"version":3},"contentHash":"dbe8e117d7887acb86f2b81d30de994a1732f20327b271d7073704bbf243668c","qualityScore":39}');
