INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ksoichiro/ChronoDawn/doc-maintenance', 'doc-maintenance', 'ksoichiro', 'ChronoDawn', 'community', 'doc-maintenance ksoichiro ChronoDawn community doc-maintenance是一个Minecraft时间维度模组，添加了Chrono Dawn时间主题世界，支持Fabric和NeoForge doc-maintenanceはMinecraftの時間テーマワールドを追加するモッドで、FabricとNeoForgeをサポート doc-maintenance는 마인크래프트 시간 차원 모드로서 Chrono Dawn 시간 테마 월드를 추가하며 Fabric와 NeoForge를 지원 Doc-maintenance es una herramienta de IA para Minecraft que agrega un mundo de tiempo con portales personalizados y batallas de jefes Doc-maintenance est un outil d''IA pour Minecraft qui ajoute un monde de temps avec des portails personnalisés et des batailles de boss Doc-maintenance ist ein KI-Tool für Minecraft, das eine Zeitwelt mit benutzerdefinierten Portalen und Bosskämpfen hinzufügt O mod doc-maintenance adiciona um mundo temático de tempo ao Minecraft com portais personalizados e artefatos de manipulação do tempo Мод doc-maintenance добавляет время-тематический мир в Minecraft с кастомными порталами и артефактами манипуляции временем يضيف مود doc-maintenance عالمًا محوريًا للزمن إلى مايﾝكرافت مع بوابات مخصصة وتحف من يمانيبولات الوقت 🕰️ A dimension mod for Minecraft that adds Chrono Dawn, a time-themed world with custom portals, boss battles, and time-manipulating artifacts. Supports Fabric & NeoForge. Minecraft模组 时间主题世界 时间操纵 Fabric模组 NeoForge模组 如何安装doc-maintenance doc-maintenance教程 Minecraft时间维度模组 AI智能代理 🕰️ A dimension mod for Minecraft that adds Chrono Dawn, a time-themed world with custom portals, boss battles, and time-manipulating artifacts. Supports Fabric & NeoForge.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tuannvm/pagent/pagent', 'community', 'tuannvm', 'pagent', 'tuannvm/pagent', 'pagent', 0, 0, 39, '2026-03-04T13:07:01.768Z', '2026-03-04T14:19:27.535Z', 'c67591fdeff366a7a61e1aafc1841f99f92062f4fa86080a23a0a07b3ce8e239', '{"id":"tuannvm/pagent/pagent","name":"pagent","description":{"zh":"pagent是一个交互式TUI，用于编排AI智能工具，输入PRD即可获得架构、测试计划、安全评估和工作代码","ja":"pagentは、AIエージェントをオーケストレーションするためのインタラクティブTUIです。PRDを入力して、構成、テスト計画、セキュリティ評価、動作コードを取得します","ko":"pagent는 AI 에이전트를 오케스트레이션하는 인터랙티브 TUI입니다. PRD를 입력하여 아키텍처, 테스트 계획, 보안 평가 및 작동 코드를 얻습니다","es":"pagent es una herramienta de interfaz de usuario interactiva que permite orquestar agentes de IA, proporcionando arquitectura, planes de prueba y código funcional","fr":"pagent est un outil d''interface utilisateur interactive qui permet d''orchestrer les agents d''IA, fournissant une architecture, des plans de test et du code fonctionnel","de":"pagent ist ein Tool mit interaktiver Benutzeroberfläche, das die Orchestrierung von AI-Agenten ermöglicht und Architektur, Testpläne und funktionierenden Code bereitstellt","pt":"O pagent é uma ferramenta interativa que orquestra agentes de IA, fornecendo arquitetura, plano de teste, avaliação de segurança e código funcional a partir de um PRD","ru":"pagent - это интерактивный инструмент, который оркеструет ИИ Агентов, предоставляя архитектуру, план тестирования, оценку безопасности и рабочий код на основе PRD","ar":"pagent هي أداة تفاعلية لتنسيق الوكلاء الذكية، وتوفر Архитيكتور، وخطة اختبار، وتقييم أمان، ورمز قابل للتشغيل من خلال وثيقة موصفة","en":"Interactive TUI to orchestrate AI agents. Give it a PRD, get back architecture, test plan, security assessment, and working code."},"seo":{"title":{"zh":"AI智能工具pagent：交互式TUI编排","ja":"AIエージェントpagent：インタラクティブTUIオーケストレーション","ko":"AI 에이전트 툴 pagent: 인터랙티브 TUI 오케스트레이션","es":"Herramientas de Agentes de I