INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BnayaZil/agent-vault-cli/npm-publish', 'npm-publish', 'BnayaZil', 'agent-vault-cli', 'community', 'npm-publish BnayaZil agent-vault-cli community npm-publish是AI代理的安全凭证存储CLI工具，通过CDP填充登录表单而不暴露凭证 npm-publishはAIエージェントのセキュアな資格情報保管CLIツールで、CDPを使用してログインフォームを埋めながら資格情報を公開しない npm-publish는 AI 에이전트의 보안 자격 증명 저장 CLI 도구로 CDP를 통해 로그인 폼을 채우면서 자격 증명을 노출하지 않습니다 npm-publish es una bóveda de credenciales seguras para Agentes de IA que llena formularios de inicio de sesión a través de CDP sin exponer credenciales, para una mayor seguridad y eficiencia npm-publish est un coffre-fort d''informations d''identification sécurisé pour les Agents IA qui remplit les formulaires de connexion via CDP sans exposer les informations d''identification, pour une sécurité et une efficacité accrues npm-publish ist ein sicherer Credential-Vault für AI-Agents, der Anmeldeformulare über CDP ausfüllt, ohne Anmeldeinformationen offenzulegen, für mehr Sicherheit und Effizienz O npm-publish é uma ferramenta de segurança para agentes de IA, permitindo o preenchimento de formulários de login via CDP sem expor credenciais. ИИ Агенты могут использовать npm-publish для безопасного хранения учетных данных и заполнения форм входа через CDP. أداة npm-publish توفر حماية لعميل الإي آي من خلال ملء استمارات تسجيل الدخول عبر بروتوكول التطوير المستمر Secure credential vault CLI for AI agents - fills login forms via CDP without exposing credentials AI代理工具 npm-publish安装 如何使用npm-publish AI代理安全凭证存储 npm-publish与其他工具比较 AI代理开发效率 npm-publish设置指南 AI代理安全开发 Secure credential vault CLI for AI agents - fills login forms via CDP without exposing credentials');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('andreaskelm/pm-brain/pm-brain-workflow', 'community', 'andreaskelm', 'pm-brain', 'andreaskelm/pm-brain', 'pm-brain-workflow', 0, 0, 39, '2026-03-04T13:07:01.851Z', '2026-03-04T14:50:24.407Z', '6ad6609520f03f2d01fc0c6446e60af97b8f9dc06f5657c157a8226a6a69728c', '{"id":"andreaskelm/pm-brain/pm-brain-workflow","name":"pm-brain-workflow","description":{"zh":"pm-brain-workflow是一个Git版本的产品管理系统，提供框架、指南、模板和游戏书，连接产品管理理论和日常执行","ja":"pm-brain-workflowは、Gitバージョンの製品管理システムであり、フレームワーク、ガイド、テンプレート、プレイブックを提供し、製品管理理論と日常の実行を接続します","ko":"pm-brain-workflow는 Git 버전의 제품 관리 시스템으로, 프레임워크, 가이드, 템플릿 및 플레이북을 제공하여 제품 관리 이론과 일일 실행을 연결합니다","es":"pm-brain-workflow es un sistema de gestión de productos basado en Git que proporciona frameworks, guías y plantillas para conectar la teoría con la ejecución diaria","fr":"pm-brain-workflow est un système de gestion de produits basé sur Git qui fournit des frameworks, des guides et des modèles pour relier la théorie à l''exécution quotidienne","de":"pm-brain-workflow ist ein Git-basiertes Produktmanagementsystem, das Frameworks, Anleitungen und Vorlagen zur Verbindung von Theorie und täglicher Umsetzung bereitstellt","pt":"O pm-brain-workflow é um sistema de gestão de produtos baseado em Git, que fornece frameworks, guias e modelos para ligar teoria e execução diária","ru":"pm-brain-workflow - система управления продуктом на основе Git, которая предоставляет фреймворки, руководства и шаблоны для соединения теории и ежедневного выполнения","ar":"pm-brain-workflow نظام إدارة المنتجات القائم على Git، يوفر الإطارات والمرشدين والنماذج للربط بين النظرية والتنفيذ اليومي","en":"Git-versioned product management system: frameworks, guides, templates, and playbooks that bridge PM theory and day-to-day execution."},"seo":{"title":{"zh":"AI智能代理pm-brain-workflow：产品管理系统","ja":"AIエージェントpm-brain-workflow：製品管理システム",