INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RamboRogers/cyber-inference/run-thor', 'run-thor', 'RamboRogers', 'cyber-inference', 'community', 'run-thor RamboRogers cyber-inference community run-thor是Cyber-Inference工具，提供自动模型管理、动态资源分配和美观的界面，适用于边缘部署 run-thorはCyber-Inferenceツールで、自動モデル管理、動的リソース割り当て、美しいインターフェースを提供し、エッジデプロイメントに適しています run-thor는 사이버 추론 도구로 자동 모델 관리, 동적 리소스 할당, 아름다운 인터페이스를 제공하며 에지 배포에 적합합니다 Run-thor es una herramienta de gestión web para servidores de inferencia compatible con OpenAI, con gestión de modelos y recursos automatizados Run-thor est un outil de gestion web pour les serveurs d''inférence compatible OpenAI, avec gestion de modèles et de ressources automatiques Run-thor ist ein Web-GUI-Tool für OpenAI-kompatible Inferenzserver mit automatisiertem Modellmanagement und dynamischer Ressourcenzuweisung O run-thor é uma ferramenta de gerenciamento web para servidores de inferência compatíveis com OpenAI, com recursos como gerenciamento automático de modelos e alocação dinâmica de recursos Run-thor - веб-инструмент для управления серверами вывода, совместимыми с OpenAI, с функциями автоматического управления моделями и динамического распределения ресурсов run-thor هي أداة إدارة الويب للخادمات الاستدلالية المتوافقة مع OpenAI، مع ميزات مثل إدارة النماذج الأوتوماتيكية وتخصيص الموارد دیناميكي Cyber-Inference is a web GUI management tool for running OpenAI-compatible inference servers. Built on llama.cpp, it provides automatic model management, dynamic resource allocation, and a beautiful cyberpunk-themed interface designed for edge deployment. AI智能代理 Cyber-Inference工具 自动模型管理 动态资源分配 边缘部署 llama.cpp run-thor安装 run-thor设置指南 Cyber-Inference is a web GUI management tool for running OpenAI-compatible inference servers. Built on llama.cpp, it provides automatic model management, dynamic resource allocation, and a beautiful cyberpunk-themed interface designed for edge deployment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vimalkodoth/fastapi-cursor-starterkit/fastapi-best-practices', 'community', 'vimalkodoth', 'fastapi-cursor-starterkit', 'vimalkodoth/fastapi-cursor-starterkit', 'fastapi-best-practices', 0, 0, 39, '2026-03-04T13:07:01.909Z', '2026-03-04T15:00:29.091Z', '84de07efcba56c9deffc519c852b8ca68c4d29e926c4cb2c418831a7ee3e20e6', '{"id":"vimalkodoth/fastapi-cursor-starterkit/fastapi-best-practices","name":"fastapi-best-practices","description":{"zh":"FastAPI Cursor Starter Kit是为AI团队提供的生产就绪后端模板，具有API-only、分层结构和内置的可观察性和质量保证","ja":"FastAPI Cursor Starter Kitは、AIエージェントチーム向けのプロダクションレディーバックエンドテンプレートです。API-only、レイヤード構造、ビルトインの観測可能性と品質保証を備えています","ko":"FastAPI Cursor Starter Kit는 AI 에이전트 팀을 위한 프로덕션 레디 백엔드 템플릿으로, API 전용, 계층 구조 및 내장 관찰 가능성 및 품질 보증을 제공합니다","es":"FastAPI Cursor Starter Kit es una plantilla de backend de producción para equipos de Cursor/AI con características de observabilidad y calidad","fr":"Le kit de démarrage FastAPI Cursor est un modèle de backend de production pour les équipes Cursor/AI avec des fonctionnalités d''observabilité et de qualité","de":"Das FastAPI Cursor Starter Kit ist eine Produktions-Backend-Vorlage für Cursor/AI-Teams mit Observability- und Qualitätsmerkmalen","pt":"FastAPI Cursor Starter Kit é um modelo de backend de produção para equipes de Cursor/AI, com camadas de endpoints, serviços e repositórios","ru":"FastAPI Cursor Starter Kit - это шаблон бэкенда для производства команд Cursor/ИИ, с уровнями конечных точек, сервисов и репозиториев","ar":"FastAPI Cursor Starter Kit هو قالب خلفية الإنتاج للفرق Cursor/AI، مع طبقات من نقاط النهاية والخدمات والمخازن","en":"FastAPI Cursor Starter Kit: production backend template for Cursor/AI teams. API-only, layered (endpoints→services→repos), Celery+RabbitMQ RPC, PostgreSQL+Alembic. Built-in observability and quality (metrics, idempotency, Black, mypy,