INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dyoshikawa/rulesync/rulesync', 'rulesync', 'dyoshikawa', 'rulesync', 'community', 'rulesync dyoshikawa rulesync community rulesync是一种AI智能代理的命令行工具，用于提高编码效率 rulesyncはAIエージェントのためのユーティリティCLIで、コーディング効率を向上させます rulesync는 AI 에이전트를 위한 유틸리티 CLI로 코딩 효율성을 향상시킵니다 Rulesync es una utilidad de línea de comandos para agentes de codificación de IA, diseñada para mejorar la productividad de los desarrolladores Rulesync est un outil en ligne de commande pour les agents de codage IA, conçu pour améliorer la productivité des développeurs Rulesync ist ein Utility-CLI-Tool für KI-Coding-Agenten, entwickelt um die Produktivität von Entwicklern zu steigern Rulesync é uma ferramenta CLI para agentes de codificação AI, projetada para melhorar a eficiência e a produtividade no desenvolvimento de software Rulesync - утилита CLI для ИИ Агентов, предназначенная для повышения эффективности и производительности в разработке программного обеспечения Rulesync هي أداة سطر الأوامر للوكلاء البرمجيين بالذكاء الاصطناعي، مصممة لتحسين الكفاءة والإنتاجية في تطوير البرمجيات A Utility CLI for AI Coding Agents rulesync AI智能代理 命令行工具 提高编码效率 如何使用rulesync rulesync安装 rulesync设置指南 AI工具 AI编码 A Utility CLI for AI Coding Agents');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RedWilly/Anima/anima', 'community', 'RedWilly', 'Anima', 'RedWilly/Anima', 'anima', 0, 0, 39, '2026-03-04T13:07:01.957Z', '2026-03-04T15:13:18.688Z', 'ee1ed0886cab0db256e77578267c2c38fb1bb9cd14425768b3808f798c0c4a98', '{"id":"RedWilly/Anima/anima","name":"anima","description":{"zh":"Anima是一个TypeScript动画引擎，支持Bun、Node.js和浏览器运行，实现精确的结构化动画","ja":"AnimaはTypeScriptアニメーションエンジンで、Bun、Node.js、ブラウザでの実行をサポートし、正確な構造化アニメーションを実現","ko":"Anima는 TypeScript 애니메이션 엔진으로, Bun, Node.js, 브라우저에서 실행할 수 있으며, 정확한 구조화 애니메이션을 구현","es":"Anima es un motor de animación de TypeScript para crear animaciones precisas y estructuradas con una salida visual limpia.","fr":"Anima est un moteur d''animation TypeScript pour créer des animations précises et structurées avec une sortie visuelle propre.","de":"Anima ist ein TypeScript-Animations-Engine für präzise und strukturierte Animationen mit einer sauberen visuellen Ausgabe.","pt":"Anima é um motor de animação TypeScript projetado para animações estruturadas e de alta precisão. Escreva o código uma vez e execute com Bun, Node.js ou diretamente no navegador. Uma versão TypeScript do conceito Manim para desenvolvedores modernos.","ru":"Anima — это TypeScript движок анимации для создания точных и структурированных анимаций. Напишите код один раз и запустите с Bun, Node.js или прямо в браузере. TypeScript-версия концепции Manim для современных разработчиков.","ar":"Anima هو محرك رسوم متحركة TypeScript مخصص للرسوم المتحركة المنظمة والدقيقة. اكتب الكود مرة واحدة وشغّله باستخدام Bun أو Node.js أو مباشرة في المتصفح. نسخة TypeScript من مفهوم Manim للمطورين الحديثين.","en":"Anima is a TypeScript animation engine built for precise, structured animations with clean visual output. Write once, then run it with Bun or Node.js, or directly in the browser. Manim on TS "},"seo":{"title":{"zh":"Anima AI工具：TypeScri