INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rohitg00/manim-video-generator/math-visualizer', 'math-visualizer', 'rohitg00', 'manim-video-generator', 'community', 'math-visualizer rohitg00 manim-video-generator community math-visualizer是使用自然语言描述创建数学动画的应用，利用OpenAI的GPT模型转换为Manim代码 math-visualizerは自然言語で数学アニメーションを作成するアプリケーションで、OpenAIのGPTモデルを使用してManimコードに変換します math-visualizer는 자연어로 수학 애니메이션을 생성하는 애플리케이션으로, OpenAI의 GPT 모델을 사용하여 Manim 코드로 변환합니다 Math-Visualizer es una aplicación que genera animaciones matemáticas a partir de descripciones en lenguaje natural utilizando GPT y Manim Math-Visualizer est une application qui génère des animations mathématiques à partir de descriptions en langage naturel en utilisant GPT et Manim Math-Visualizer ist eine Anwendung, die mathematische Animationen aus natürlichen Sprachbeschreibungen mit GPT und Manim generiert O Math-Visualizer é uma aplicação que gera animações matemáticas usando descrições em linguagem natural, com o uso do modelo GPT da OpenAI Math-Visualizer - это приложение, которое генерирует математические анимации с помощью описаний на естественном языке, используя модель GPT от OpenAI Math-Visualizer هو تطبيق يولد الرسوم المتحركة الرياضية باستخدام الوصف باللغة الطبيعية، مع استخدام نموذج GPT من OpenAI This application allows you to generate mathematical animations using natural language descriptions. It uses OpenAI''s GPT model to convert your descriptions into Manim code, which is then used to create beautiful mathematical animations. 如何使用math-visualizer 什么是math-visualizer math-visualizer替代品 math-visualizer安装 math-visualizer教程 使用自然语言创建数学动画 OpenAI GPT模型 Manim代码生成 This application allows you to generate mathematical animations using natural language descriptions. It uses OpenAI''s GPT model to convert your descriptions into Manim code, which is then used to create beautiful mathematical animations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nexus-labs-automation/mobile-observability/session-replay', 'community', 'nexus-labs-automation', 'mobile-observability', 'nexus-labs-automation/mobile-observability', 'session-replay', 0, 0, 38, '2026-03-04T13:07:01.674Z', '2026-03-04T13:23:25.666Z', '044e03c3c8cfdb2f4f5e5062fbb302ab78ce60692bd13c276a0399547e172f43', '{"id":"nexus-labs-automation/mobile-observability/session-replay","name":"session-replay","description":{"zh":"Claude Code AI智能代理会话回放插件提供移动应用崩溃报告、性能监控和仪表化，支持iOS、Android和React Native","ja":"Claude CodeのAIエージェントセッションリプレイプラグインは、モバイルアプリのクラッシュレポート、パフォーマンスモニタリング、インストルメンテーションを提供","ko":"Claude Code AI 에이전트 세션 리플레이 플러그인은 모바일 앱의 크래시 리포팅, 성능 모니터링, 인스트루멘테이션을 제공","es":"Session Replay es un plugin de Claude Code para la observabilidad de aplicaciones móviles, que ofrece informes de errores, monitoreo de rendimiento e instrumentación para iOS, Android y React Native.","fr":"Session Replay est un plugin Claude Code pour l''observabilité des applications mobiles, qui propose des rapports d''erreurs, un suivi des performances et une instrumentation pour iOS, Android et React Native.","de":"Session Replay ist ein Plugin von Claude Code für die Observabilität mobiler Anwendungen, das Fehlerberichte, Leistungsüberwachung und Instrumentierung für iOS, Android und React Native bietet.","pt":"O Claude Code é um plugin para observabilidade de aplicativos móveis, oferecendo relatórios de falhas, monitoramento de desempenho e instrumentação para iOS, Android e React Native","ru":"Claude Code - это плагин для наблюдаемости мобильных приложений, предлагающий отчеты о сбоях, мониторинг производительности и инструменты для iOS, Android и React Native","ar":"كلود كود هو مكون إضافي لمراقبة التطبيقات المحمولة، يقدم تقارير الأعطال ومراقبة الأداء والآلات لآي أو إس وأندرويد وري액ت نيتيف","en":"Claude Code plugin for mobile app o