INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alexandru/social-publish/arrow-resource', 'arrow-resource', 'alexandru', 'social-publish', 'community', 'arrow-resource alexandru social-publish community arrow-resource是一个自托管服务，帮助开发者同时分享内容到多个社交媒体平台 arrow-resourceは、開発者が複数のソーシャルメディアへの同時共有を支援する自托管サービスです arrow-resource는 개발자가 여러 소셜 미디어 플랫폼에 동시에 공유할 수 있도록 지원하는 자체 호스팅 서비스입니다 arrow-resource es un servicio de autoservicio que permite compartir contenido en varias redes sociales al mismo tiempo arrow-resource est un service en libre-service qui permet de partager du contenu sur plusieurs réseaux sociaux en même temps arrow-resource ist ein Self-Service, der das Teilen von Inhalten auf mehreren sozialen Medienplattformen gleichzeitig ermöglicht O arrow-resource é um serviço de auto-hospedagem que permite compartilhar conteúdo em várias plataformas de mídia social de forma simultânea ИИ Агент arrow-resource - это самохостящийся сервис, который позволяет делиться контентом на нескольких социальных платформах одновременно آلة arrow-resource هي خدمة ذاتية الاستضافة تتيح مشاركة المحتوى على عدة منصات إعلامية اجتماعية في نفس الوقت Self-hosted service that helps me share to multiple social media platforms at the same time. 如何使用arrow-resource 什么是AI智能代理 arrow-resource替代品 arrow-resource与其他工具的比较 arrow-resource安装 arrow-resource设置指南 社交媒体分享工具 自托管服务 Self-hosted service that helps me share to multiple social media platforms at the same time.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AndreaCadonna/serverless_function_runtime/code-quality', 'community', 'AndreaCadonna', 'serverless_function_runtime', 'AndreaCadonna/serverless_function_runtime', 'code-quality', 0, 0, 38, '2026-03-04T13:07:01.708Z', '2026-03-04T13:42:39.158Z', '99780de266bc7374930a433f0b9557627129a6f0a70b4d10f2228be04815a976', '{"id":"AndreaCadonna/serverless_function_runtime/code-quality","name":"code-quality","description":{"zh":"代码质量是一个本地服务器less运行时，映射文件到HTTP端点，使用严格的Web请求和响应合同","ja":"コード品質はローカルサーバーレスランタイムであり、ファイルをHTTPエンドポイントにマッピングし、厳格なWebリクエストとレスポンス契約を使用","ko":"코드 품질은 로컬 서버리스 런타임이며 파일을 HTTP 엔드포인트에 매핑하고 엄격한 웹 요청 및 응답 계약을 사용","es":"Nuestro agente de calidad de código es un entorno de ejecución local sin servidor que mapea archivos en api/ a endpoints HTTP","fr":"Notre outil de qualité de code est un environnement d''exécution local sans serveur qui mappe les fichiers en api/ à des endpoints HTTP","de":"Unser Code-Qualitäts-Tool ist eine lokale Laufzeitumgebung ohne Server, die Dateien in api/ auf HTTP-Endpunkte abbildet","pt":"O Code-Quality é uma solução de tempo de execução sem servidor local que mapeia arquivos em api/ para pontos de extremidade HTTP e dispatcha solicitações usando um contrato estrito de Solicitação da Web -> Resposta.","ru":"Code-Quality - это локальная серверная среда выполнения, которая сопоставляет файлы в api/ с конечными точками HTTP и.dispatches запросов, используя строгий контракт Веб-запроса -> Ответа.","ar":"Code-Quality هو حل Runtime بدون خادم محلي يربط الملفات في api/ بنقاط النهاية HTTP ويستخدم عقد стрickt لطلب الويب -> استجابة","en":"Local serverless runtime that maps files in api/ to HTTP endpoints and dispatches requests using a strict Web Request -> Response contract."},"seo":{"title":{"zh":"AI智能代码质量工具 - 代码质量检查","ja":"AIエージェントのコード品質 - コード品質チェック","ko":"AI 에이전트 코드 품질 - 코드 품질 확인","es":"Her