INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kks0488/vibe-codex/vcf', 'vcf', 'kks0488', 'vibe-codex', 'community', 'vcf kks0488 vibe-codex community vcf是AI-first技能的代表，实现自主编码，具有快速循环和零设置的特点，兼容Codex和OpenCode vcfはAIエージェントの代表であり、オートノマスコーディングを実現し、高速ループとゼロセットアップの特徴を持つ、CodexおよびOpenCodeとの互換性 vcf는 AI 에이전트의 대표적인 예로 자율 코딩을 실현하며 빠른 루프와 설정 없이의 특징을 가지고 있으며, Codex 및 OpenCode와의 호환성을 지원 vcf es una habilidad de AI-first que permite la codificación autónoma con bucles rápidos y zero-setup, compatible con Codex y OpenCode vcf est une compétence d''IA première qui permet le codage autonome avec des boucles rapides et un zero-setup, compatible avec Codex et OpenCode vcf ist eine KI-erste Fähigkeit, die das autonome Coden mit schnellen Schleifen und Zero-Setup ermöglicht, kompatibel mit Codex und OpenCode O vcf é uma habilidade de IA para codificação autônoma, compatível com Codex e OpenCode, com loops rápidos e zero configuração Vcf - навык ИИ для автономного кодирования, совместимый с Codex и OpenCode, с быстрыми циклами и нулевой настройкой vcf هو مهارة الذكاء الاصطناعي للبرمجة المستقلة، متوافق مع Codex و OpenCode، مع حلقات سريعة وبدون إعداد ⚡ AI-first skills for autonomous coding. Fast loops, zero-setup, Codex & OpenCode compatible. AI智能代理 自主编码 快速循环 零设置 Codex OpenCode AI-first技能 如何使用vcf vcf安装 vcf设置指南 ⚡ AI-first skills for autonomous coding. Fast loops, zero-setup, Codex & OpenCode compatible.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sanmak/kritarch-lite/security-env', 'community', 'sanmak', 'kritarch-lite', 'sanmak/kritarch-lite', 'security-env', 0, 0, 38, '2026-03-04T13:07:01.749Z', '2026-03-04T14:10:57.413Z', '142f3a8c5422c3e299830a4659635d6023bcfb45b072d2350874b277898ecee1', '{"id":"sanmak/kritarch-lite/security-env","name":"security-env","description":{"zh":"Kritarch Lite安全环境AI工具提供多角度分析和结构化结论，帮助开发者提高工作效率","ja":"Kritarch Liteのセキュリティ環境AIエージェントは、多角度分析と構造化された結論を提供して開発者の仕事の効率を向上させます","ko":"Kritarch Lite 보안 환경 AI 에이전트는 多角度 분석과 구조화된 결론을 제공하여 개발자의 작업 효율성을 향상합니다","es":"Kritarch Lite ofrece un panel de Agentes de IA que analizan problemas de seguridad-env y entregan un veredicto estructurado","fr":"Kritarch Lite propose un panel d''Agents d''IA qui analysent les problèmes de sécurité-env et livrent un verdict structuré","de":"Kritarch Lite bietet ein Panel von KI-Agents, die Sicherheits-probleme von security-env analysieren und ein strukturiertes Urteil liefern","pt":"A Kritarch Lite oferece painel de agentes de IA que analisam problemas de segurança de ângulos competitivos, desafiando o raciocínio uns dos outros e entregando um veredito estruturado","ru":"Kritarch Lite предлагает панель ИИ Агентов, которые анализируют проблемы безопасности с конкурирующих углов,挑ая друг друга и доставляя структурированный вердикт","ar":"توفر Kritarch Lite لوحة من وكلاء الذكاء الاصطناعي الذين يتحليلون مشاكل الأمان من زوايا تنافسية، ويتحدون التفكير بعضهم البعض وتقديم حكم منظم","en":"Kritarch Lite gives you a panel of AI agents that analyze the problem from competing angles, challenge each other''s reasoning, and deliver a structured verdict. You review the conclusion, not the process."},"seo":{"title":{"zh":"安全环境AI工具 - security-env","ja":"セキュリティ環境AIエージェント - security-env","ko":"보안 환경 AI 에이전트 - security-env","es":"Herramientas de seguridad-env con Agentes de I