INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chrispangg/deepagentsdk/content-writer', 'content-writer', 'chrispangg', 'deepagentsdk', 'community', 'content-writer chrispangg deepagentsdk community content-writer是一个基于Vercel AI SDK v6构建的AI代理框架，帮助开发者快速集成AI功能到应用中，支持多种开发语言和平台。 content-writerは、Vercel AI SDK v6を基盤とするAIエージェントフレームワークで、開発者がアプリにAI機能を簡単に統合できるように設計されています。 content-writer는 Vercel AI SDK v6를 기반으로 한 AI 에이전트 프레임워크로, 개발자가 애플리케이션에 AI 기능을 쉽게 통합할 수 있도록 지원합니다. Content Writer es un framework de Deep Agent Harness construido con Vercel AI SDK v6 para desarrolladores Content Writer est un framework de Deep Agent Harness construit avec Vercel AI SDK v6 pour les développeurs Content Writer ist ein Framework von Deep Agent Harness, entwickelt mit Vercel AI SDK v6 für Entwickler O content-writer é um framework de agente de IA construído com Vercel''s AI SDK v6, projetado para automatizar e otimizar a criação de conteúdo técnico para desenvolvedores. content-writer — это фреймворк для ИИ агентов, созданный на Vercel AI SDK v6, предназначенный для автоматизации и оптимизации создания технического контента для разработчиков. content-writer هو إطار عمل لوكلاء الذكاء الاصطناعي مبني على Vercel AI SDK v6، مصمم لأتمتة وتحسين إنشاء المحتوى التقني للمطورين. A Deep Agent Harness framework built with Vercel''s AI SDK v6 AI代理框架 Vercel AI SDK使用指南 content-writer安装 AI工具集成 React AI代理 Node.js AI开发 content-writer vs其他框架 如何部署AI代理 A Deep Agent Harness framework built with Vercel''s AI SDK v6');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sorryhyun/DiPeO/dipeo-backend', 'community', 'sorryhyun', 'DiPeO', 'sorryhyun/DiPeO', 'dipeo-backend', 12, 2, 37, '2026-02-06T07:13:58Z', '2026-02-26T08:34:19.486Z', '385b8298fdd6d15a17afaca6765fd67fe313081962210da9928e8561400ca9af', '{"id":"sorryhyun/DiPeO/dipeo-backend","name":"dipeo-backend","description":{"zh":"dipeo-backend是基于块图UI的AI智能代理工具构建平台，帮助开发者快速创建和管理工具","ja":"dipeo-backendはブロック図UIを使用したAIエージェントのツール構築プラットフォームで、開発者が迅速にツールを作成して管理できるようにします","ko":"dipeo-backend는 블록 다이어그램 UI를 기반으로 하는 AI 에이전트 툴 빌드 플랫폼으로 개발자가 빠르게 툴을 생성하고 관리할 수 있습니다","es":"Dipeo-backend es una herramienta de construcción de agentes de inteligencia artificial que utiliza una interfaz de diagrama de bloques para facilitar el desarrollo","fr":"Dipeo-backend est un outil de construction d''agents d''intelligence artificielle qui utilise une interface de diagramme de blocs pour faciliter le développement","de":"Dipeo-backend ist ein Tool zum Erstellen von KI-Agents, das eine Blockdiagramm-Oberfläche verwendet, um die Entwicklung zu erleichtern","pt":"O dipeo-backend é uma ferramenta de construção de agentes que utiliza uma interface de diagrama de blocos para facilitar o desenvolvimento","ru":"Dipeo-backend - это инструмент для создания агентов, использующий блок-схему для упрощения разработки","ar":"dipeo-backend هو أداة لبناء الوكلاء التي تستخدم واجهة الرسم بالكتلة لتسهيل التطوير","en":"Agent building tools via block diagram UI"},"seo":{"title":{"zh":"AI智能代理dipeo-backend：基于块图UI的工具构建","ja":"AIエージェントdipeo-backend：ブロック図UIによるツール構築","ko":"AI 에이전트 dipeo-backend: 블록 다이어그램 UI를 통한 툴 빌드","es":"Herramientas de agente de inteligencia artificial dipeo-b...","fr":"Outils d''agent d''intelligence artificielle dipeo-backend","de":"KI-Agent-Tools dipeo-backend","pt":"Ferramentas de Agente de IA: dipeo-backend","ru":"ИИ Агенты: dipeo-backend","ar":"أدوات الوك