INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('omniaura/omniclaw/migrate-to-channels', 'migrate-to-channels', 'omniaura', 'omniclaw', 'community', 'migrate-to-channels omniaura omniclaw community migrate-to-channels 是一个始终在线的编码代理，驻扎在您的团队聊天中，提供实时编码协助 migrate-to-channels は、常にオンラインのコーディングエージェントで、グループチャットに駐在し、リアルタイムのコーディング支援を提供します migrate-to-channels 는 그룹 채팅中的 실시간 코딩 지원을 제공하는 항상 온라인 코딩 에이전트입니다 migrate-to-channels es un agente de código siempre activo que vive en tus chats de grupo, mejorando tu productividad migrate-to-channels est un agent de codage toujours actif qui vit dans vos chats de groupe, améliorant votre productivité migrate-to-channels ist ein immer aktiver Code-Agent, der in Ihren Gruppenchats lebt und Ihre Produktivität verbessert O agente de codificação AI ''migrate-to-channels'' é um assistente de codificação sempre ativo que vive nos chats de grupo, ajudando a migrar para canais de forma eficiente ИИ агент ''migrate-to-channels'' является всегда-активным помощником по кодированию, живущим в групповых чатах, помогающим мигрировать на каналы эффективно وكيل الترميز الإصطناعي ''migrate-to-channels'' هو مساعد ترميز دائم الفعالية يعيش في المحادثات الجماعية، مما يساعد في الهجرة إلى القنوات بفعالية Always-on coding agent that lives in your group chats 如何使用 migrate-to-channels 什么是 AI 智能代理 migrate-to-channels 替代品 migrate-to-channels 安装 migrate-to-channels 教程 实时编码协助工具 Always-on coding agent that lives in your group chats');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ferrucc-io/clog/reproduce', 'community', 'ferrucc-io', 'clog', 'ferrucc-io/clog', 'reproduce', 2, 0, 37, '2026-02-27T20:02:30Z', '2026-02-28T01:38:41.799Z', 'd452ac7c230fd9e1b40a2097334b8ea8599a1f7c1129cdebc8ce8115a1663bb1', '{"id":"ferrucc-io/clog/reproduce","name":"reproduce","description":{"zh":"reproduce是一种CLI + Skill，用于与Claude Code一起进行调试，提高开发效率","ja":"reproduceは、Claude Codeとともにデバッグを行うためのCLI + スキルで、開発効率を向上","ko":"reproduce는 Claude Code와 함께 디버깅을 수행하는 CLI + 스킬로 개발 효율성을 높입니다","es":"Reproduce es una herramienta de línea de comandos (CLI) para depuración con Claude Code, diseñada para desarrolladores","fr":"Reproduce est un outil en ligne de commande (CLI) pour le débogage avec Claude Code, conçu pour les développeurs","de":"Reproduce ist ein Kommandozeilen-Tool (CLI) für das Debugging mit Claude Code, entwickelt für Entwickler","pt":"O skill de reprodução é uma ferramenta de linha de comando para depurar com Claude Code, permitindo que os desenvolvedores resolvam problemas de forma eficiente","ru":"Навык воспроизведения - это инструмент командной строки для отладки с Claude Code, позволяющий разработчикам эффективно решать проблемы","ar":"مهارة إعادة الإنتاج هي أداة سطر أوامر لتصحيح الأخطاء مع Claude Code، مما يسمح للمطورين بحل المشكلات بفعالية","en":"A CLI + Skill for debugging with Claude Code"},"seo":{"title":{"zh":"AI工具：reproduce 调试CLI技能","ja":"AIエージェント：reproduce デバッグCLIスキル","ko":"AI 에이전트: reproduce 디버깅 CLI 스킬","es":"Herramientas de AI: Reproduce CLI para Depuración","fr":"Outils d''IA: Reproduce CLI pour le Débogage","de":"KI-Tools: Reproduce CLI für Debugging","pt":"Ferramentas de IA: Reproduzir com Claude Code","ru":"ИИ Агенты: Reproduce с Claude Code","ar":"أدوات الذكاء الاصطناعي: إعادة إنتاج مع Claude Code","en":"reproduce"},"description":{"zh":"reproduce是一种CLI + Skill，用于与Claude Code一起进行调试，提高开发效率","ja":"reproduceは、Claude Codeとともにデバッグを行うためのCLI + スキルで、開発効率を向上","ko":"reproduce는 Claude Code와 함께 디버깅을 수행하는 CLI + 스킬로 개발 효율성을 높입니다","es":"Reproduce es una herramienta de línea de comandos (CLI) para depuración con Claude Code, diseñada para desarrolladores","fr":"Reproduce est un outil en ligne de commande (CLI) pour le débogage avec Claude Code, conçu pour les développeurs","de":"Reproduce ist ein Kommandozeilen-Tool (CLI) für das Debugging mit Claude Code, entwickelt für Entwickler","pt":"O skill de reprodução é uma ferramenta de linha de comando para depurar com Claude Code, permitindo que os desenvolvedores resolvam problemas de forma eficiente","ru":"Навык воспроизведения - это инструмент командной строки для отладки с Claude Code, позволяющий разработчикам эффективно решать проблемы","ar":"مهارة إعادة الإنتاج هي أداة سطر أوامر لتصحيح الأخطاء مع Claude Code، مما يسمح للمطورين بحل المشكلات بفعالية","en":"A CLI + Skill for debugging with Claude Code"},"definition":{"en":"A CLI + Skill for debugging with Claude Code"},"features":{"zh":["CLI接口","与Claude Code集成","提高调试效率","支持多种开发语言","简化开发流程"],"ja":["CLIインターフェース","Claude Codeとの統合","デバッグ効率の向上","複数の開発言語をサポート","開発プロセスの簡素化"],"ko":["CLI 인터페이스","Claude Code와의 통합","디버깅 효율성 향상","다중 개발 언어 지원","개발 프로세스 간소화"],"es":["Depuración con Claude Code","Interfaz de línea de comandos (CLI)","Herramienta de AI para desarrolladores","Mejora de habilidades de depuración","Integración con Claude Code"],"fr":["Débogage avec Claude Code","Interface en ligne de commande (CLI)","Outil d''IA pour les développeurs","Amélioration des compétences en débogage","Intégration avec Claude Code"],"de":["Debugging mit Claude Code","Kommandozeilen-Interface (CLI)","KI-Tool für Entwickler","Verbesserung der Fähigkeiten im Debugging","Integration mit Claude Code"],"pt":["Depuração com Claude Code","Ferramenta de linha de comando","Resolução eficiente de problemas","Integração com CLI","Suporte a desenvolvedores"],"ru":["Отладка с Claude Code","Инструмент командной строки","Эффективное решение проблем","Интеграция с CLI","Поддержка разработчиков"],"ar":["تصحيح الأخطاء مع Claude Code","أداة سطر أوامر","حل فعال للمشكلات","التكامل مع CLI","دعم المطورين"]},"keywords":{"zh":["AI工具","reproduce安装","CLI调试","Claude Code教程","如何使用reproduce","reproduce替代品","reproduce与其他工具的比较","开发效率提高","调试技巧"],"ja":["AIエージェント","reproduceのインストール","CLIデバッグ","Claude Codeのチュートリアル","reproduceの使い方","reproduceの代替","reproduceと他のツールの比較","開発効率の向上","デバッグテクニック"],"ko":["AI 에이전트","reproduce 설치","CLI 디버깅","Claude Code 튜토리얼","reproduce 사용법","reproduce 대체","reproduce와 다른 툴의 비교","개발 효율성 향상","디버깅 기술"],"es":["herramientas de AI","depuración con Claude Code","reproduce CLI","cómo usar reproduce","alternativas a reproduce","reproduce vs otros depuradores","instalación de reproduce","guía de configuración de reproduce"],"fr":["outils d''IA","débogage avec Claude Code","reproduce CLI","comment utiliser reproduce","alternatives à reproduce","reproduce vs autres débogueurs","installation de reproduce","guide de configuration de reproduce"],"de":["KI-Tools","Debugging mit Claude Code","reproduce CLI","wie man reproduce verwendet","alternativen zu reproduce","reproduce vs andere debugger","installation von reproduce","konfigurationsanleitung für reproduce"],"pt":["como usar o skill de reprodução","o que é o skill de reprodução","ferramentas de ia para desenvolvedores","alternativas ao claude code","claude code vs outros","instalar o skill de reprodução","guia de configuração do skill de reprodução"],"ru":["как использовать навык воспроизведения","что такое навык воспроизведения","инструменты ии для разработчиков","альтернативы claude code","claude code vs другие","установить навык воспроизведения","руководство по настройке навыка воспроизведения"],"ar":["كيفية استخدام مهارة إعادة الإنتاج","ما هي مهارة إعادة الإنتاج","أدوات الذكاء الاصطناعي للمطورين","بديلات كلود كود","كلود كود مقابل غيره","تثبيت مهارة إعادة الإنتاج","دليل إعداد مهارة إعادة الإنتاج"]}},"owner":"ferrucc-io","repo":"clog","repoPath":"ferrucc-io/clog","stars":2,"forks":0,"updatedAt":"2026-02-27T20:02:30Z","topics":[],"category":"community","skillMd":{"name":"reproduce","description":"Debug a users bug by instrumenting their code with clog log statements, having them reproduce the issue, then analyzing the logs to find root cause","bodyPreview":"# Debug with clog\n\nYou are a debugging assistant. You use `clog` — a local log ingestion CLI — to help the user find the root cause of a bug. The workflow is: instrument code with log statements that POST to clog, have the user reproduce the bug, then analyze the captured logs.\n\n## Prerequisites\n\nBefore starting, make sure the clog server is running:\n\n```bash\nclog status\n```\n\nIf it''s not running, start it:\n\n```bash\nclog start\n```\n\nIf `clog` is not installed, tell the user to install it:\n```\ncarg","body":"# Debug with clog\n\nYou are a debugging assistant. You use `clog` — a local log ingestion CLI — to help the user find the root cause of a bug. The workflow is: instrument code with log statements that POST to clog, have the user reproduce the bug, then analyze the captured logs.\n\n## Prerequisites\n\nBefore starting, make sure the clog server is running:\n\n```bash\nclog status\n```\n\nIf it''s not running, start it:\n\n```bash\nclog start\n```\n\nIf `clog` is not installed, tell the user to install it:\n```\ncargo install --path <path-to-clog-repo>\n```\n\nThe clog server always runs on port **2999**.\n\n## Step 1: Understand the bug\n\nAsk the user:\n- What is the bug? What''s the expected vs actual behavior?\n- Where in the codebase do they think the problem is? (file, function, flow)\n- How do they reproduce it?\n\nIf the user already described the bug (e.g. as an argument to `/debug`), skip straight to investigating the relevant code area. Use `$ARGUMENTS` as the bug description if provided.\n\n## Step 2: Instrument the code\n\nRead the relevant source files and add logging statements that POST JSON to clog. Choose the right language for the user''s codebase:\n\n**Python:**\n```python\nimport urllib.request, json\ndef _clog(data):\n    try:\n        urllib.request.urlopen(urllib.request.Request(\n            \"http://localhost:2999/log\",\n            data=json.dumps(data).encode(),\n            headers={\"Content-Type\": \"application/json\"},\n            method=\"POST\"))\n    except: pass\n```\n\n**JavaScript/TypeScript (Node):**\n```javascript\nfunction _clog(data) {\n  fetch(\"http://localhost:2999/log\", {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(data),\n  }).catch(() => {});\n}\n```\n\n**Rust:**\n```rust\nfn _clog(data: &impl serde::Serialize) {\n    let _ = reqwest::blocking::Client::new()\n        .post(\"http://localhost:2999/log\")\n        .json(data)\n        .send();\n}\n```\n\n**Shell/curl:**\n```bash\ncurl -s -X POST http://localhost:2999/log \\\n  -H ''Content-Type: application/json'' \\\n  -d ''{\"step\":\"description\",\"value\":\"...\"}''\n```\n\n### What to log\n\nPlace log statements at key points in the suspected code path:\n- Function entry/exit with argument values\n- Branch decisions (which `if`/`else`/`match` arm was taken)\n- Variable values before and after transformations\n- Loop iterations with index and relevant state\n- Error catch blocks with the error details\n- API request/response payloads\n\nEach log payload should include a `\"step\"` field describing where in the flow it is, plus whatever data is relevant. Example:\n\n```python\n_clog({\"step\": \"validate_input\", \"user_id\": user_id, \"payload\": payload})\n_clog({\"step\": \"db_query_result\", \"rows\": len(rows), \"first\": rows[0] if rows else None})\n_clog({\"step\": \"transform_output\", \"before\": raw, \"after\": transformed})\n```\n\nKeep log statements minimal and non-invasive — they should not change control flow.\n\n## Step 3: Ask the user to reproduce\n\nOnce instrumentation is in place, tell the user:\n\n> I''ve added debug logging to the code. Please reproduce the bug now — do exactly what triggers the issue. Let me know when you''re done.\n\nWait for the user to confirm they''ve reproduced the bug before proceeding.\n\n## Step 4: Analyze the logs\n\nClear any old logs first if you started fresh, otherwise look at recent entries:\n\n```bash\nclog latest -n 50\n```\n\nFor targeted searches, use grep on the log file directly:\n\n```bash\ngrep \"step\" ~/.clog/logs/clog.ndjson\n```\n\nOr use `clog latest` with a filter:\n\n```bash\nclog latest -n 100 -q \"error\"\nclog latest -n 100 -q \"step_name\"\n```\n\nFor more powerful searches, use ripgrep:\n\n```bash\nrg \"pattern\" ~/.clog/logs/clog.ndjson\n```\n\n### Analysis approach\n\n1. **Trace the flow** — read logs chronologically to see what path the code took\n2. **Find the divergence** — identify where actual behavior deviated from expected\n3. **Inspect values** — look at variable states at the divergence point\n4. **Check for missing logs** — if an expected log step is absent, that code path wasn''t reached\n5. **Correlate timestamps** — use the `ts` field to identify timing issues or ordering problems\n\n## Step 5: Report findings and fix\n\nOnce you''ve identified the root cause:\n\n1. Explain to the user what you found, referencing specific log entries\n2. Propose a fix\n3. Remove all the `_clog` instrumentation you added (the logging was temporary)\n4. Clean up: `clog clear`\n\n## Important notes\n\n- Always remove instrumentation after debugging. The `_clog` calls are not production code.\n- If the first round of logs isn''t enough, add more targeted instrumentation and ask the user to reproduce again.\n- If `clog status` shows the server is dead mid-session, restart it with `clog start`.\n- The log file is at `~/.clog/logs/clog.ndjson` — each line is `{\"ts\":\"...\",\"data\":{...}}`.\n"},"lastSynced":"2026-02-28T01:38:41.799Z","agentAnalysis":{"suitability":{"en":"Ideal for Debugging Agents requiring real-time log analysis and root cause identification.","zh":"非常适合需要实时日志分析和根本原因识别的调试代理。","ja":"リアルタイムのログ分析と根本原因の特定を必要とするデバッグエージェントに最適です。","ko":"실시간 로그 분석 및 근본 원인 식별이 필요한 디버깅 에이전트에 이상적입니다.","es":"Ideal para depurar Agents que requieren análisis de logs en tiempo real e identificación de la causa raíz.","fr":"Idéal pour le débogage d''Agents nécessitant une analyse de logs en temps réel et une identification de la cause racine.","de":"Ideal zum Debuggen von Agents, die Echtzeit-Log-Analyse und die Identifizierung der Ursache erfordern.","pt":"Ideal para Agentes de Depuração que requerem análise de logs em tempo real e identificação da causa raiz.","ru":"Идеально подходит для отладочных агентов, требующих анализа журналов в реальном времени и определения первопричины.","ar":"مثالي لوكلاء التصحيح الذين يتطلبون تحليل السجلات في الوقت الفعلي وتحديد السبب الجذري."},"recommendation":{"en":"Enables agents to analyze runtime behavior through captured log streams from clog instrumentation. Provides direct access to structured debugging data via local HTTP POST endpoints for precise bug reproduction scenarios.","zh":"通过从 clog 检测捕获的日志流，使代理能够分析运行时行为。通过本地 HTTP POST 端点提供对结构化调试数据的直接访问，以实现精确的错误复现场景。","ja":"clog インストルメンテーションからキャプチャされたログストリームを通じて、エージェントがランタイム動作を分析できるようにします。正確なバグ再現シナリオのために、ローカル HTTP POST エンドポイントを介して構造化されたデバッグデータへの直接アクセスを提供します。","ko":"clog 인스트루멘테이션에서 캡처한 로그 스트림을 통해 에이전트가 런타임 동작을 분석할 수 있도록 합니다. 정확한 버그 재현 시나리오를 위해 로컬 HTTP POST 엔드포인트를 통해 구조화된 디버깅 데이터에 대한 직접 액세스를 제공합니다.","es":"Permite a los agents analizar el comportamiento en tiempo de ejecución mediante flujos de logs capturados de la instrumentación clog. Proporciona acceso directo a datos de depuración estructurados a través de endpoints HTTP POST locales para escenarios precisos de reproducción de errores.","fr":"Permet aux agents d''analyser le comportement d''exécution via des flux de logs capturés provenant de l''instrumentation clog. Fournit un accès direct aux données de débogage structurées via des endpoints HTTP POST locaux pour des scénarios de reproduction de bugs précis.","de":"Ermöglicht Agents, das Laufzeitverhalten durch erfasste Log-Streams von clog-Instrumentierung zu analysieren. Bietet direkten Zugriff auf strukturierte Debug-Daten über lokale HTTP POST Endpoints für präzise Bug-Reproduktionsszenarien.","pt":"Permite que os agentes analisem o comportamento em tempo de execução por meio de fluxos de logs capturados da instrumentação clog. Fornece acesso direto a dados estruturados de depuração via endpoints locais HTTP POST para cenários precisos de reprodução de bugs.","ru":"Позволяет агентам анализировать поведение во время выполнения через захваченные потоки журналов из инструментирования clog. Обеспечивает прямой доступ к структурированным отладочным данным через локальные конечные точки HTTP POST для точных сценариев воспроизведения ошибок.","ar":"يمكن الوكلاء من تحليل سلوك وقت التشغيل من خلال تدفقات السجلات التي تم التقاطها من أداة clog. يوفر وصولاً مباشراً إلى بيانات التصحيح المنظمة عبر نقاط نهاية HTTP POST المحلية لحالات استنساخ الأخطاء بدقة."},"useCases":{"en":["Analyzing runtime execution flows","Identifying root causes from instrumented logs","Reproducing bugs through captured log sequences","Debugging with structured log ingestion"],"zh":["分析运行时执行流","从检测日志中识别根本原因","通过捕获的日志序列重现错误","通过结构化日志摄取进行调试"],"ja":["ランタイム実行フローの分析","インストルメント化されたログからの根本原因の特定","キャプチャされたログシーケンスによるバグの再現","構造化ログインジェスションによるデバッグ"],"ko":["런타임 실행 흐름 분석","인스트루멘트화된 로그에서 근본 원인 식별","캡처된 로그 시퀀스를 통한 버그 재현","구조화된 로그 수집을 통한 디버깅"],"es":["Analizar flujos de ejecución en tiempo de ejecución","Identificar causas raíz a partir de logs instrumentados","Reproducir errores mediante secuencias de logs capturadas","Depurar con ingesta de logs estructurados"],"fr":["Analyser les flux d''exécution en temps d''exécution","Identifier les causes racines à partir de logs instrumentés","Reproduire les bugs via des séquences de logs capturées","Déboguer avec l''ingestion de logs structurés"],"de":["Analysieren von Laufzeitausführungsflüssen","Identifizieren von Ursachen aus instrumentierten Logs","Reproduzieren von Bugs durch erfasste Log-Sequenzen","Debuggen mit strukturierter Log-Erfassung"],"pt":["Analisando fluxos de execução em tempo de execução","Identificando causas raiz a partir de logs instrumentados","Reproduzindo bugs por meio de sequências de logs capturadas","Depurando com ingestão estruturada de logs"],"ru":["Анализ потоков выполнения во время выполнения","Определение первопричин из инструментированных журналов","Воспроизведение ошибок через захваченные последовательности журналов","Отладка со структурированным приемом журналов"],"ar":["تحليل تدفقات تنفيذ وقت التشغيل","تحديد الأسباب الجذرية من السجلات المؤداة","استنساخ الأخطاء من خلال تسلسلات السجلات التي تم التقاطها","التصحيح مع تناول منظم للسجلات"]},"limitations":{"en":["Requires clog server running locally","Needs code instrumentation with POST statements","Dependent on user reproducing the bug","Requires clog CLI installation"],"zh":["需要在本地运行 clog 服务器","需要使用 POST 语句进行代码检测","依赖于用户重现错误","需要安装 clog CLI"],"ja":["ローカルで実行されている clog サーバーが必要","POST ステートメントを使用したコードインストルメンテーションが必要","ユーザーによるバグの再現に依存","clog CLI のインストールが必要"],"ko":["로컬에서 실행 중인 clog 서버 필요","POST 문을 사용한 코드 인스트루멘테이션 필요","사용자가 버그를 재현해야 함","clog CLI 설치 필요"],"es":["Requiere que el servidor clog esté ejecutándose localmente","Necesita instrumentación de código con declaraciones POST","Depende de que el usuario reproduzca el error","Requiere la instalación de clog CLI"],"fr":["Nécessite que le serveur clog soit exécuté localement","Nécessite une instrumentation du code avec des instructions POST","Dépend de la reproduction du bug par l''utilisateur","Nécessite l''installation de clog CLI"],"de":["Erfordert, dass der clog-Server lokal läuft","Benötigt Code-Instrumentierung mit POST-Anweisungen","Abhängig davon, dass der Benutzer den Bug reproduziert","Erfordert die Installation der clog CLI"],"pt":["Requer que o servidor clog esteja em execução localmente","Necessita de instrumentação de código com instruções POST","Dependente do usuário reproduzir o bug","Requer instalação do CLI clog"],"ru":["Требует локально запущенного сервера clog","Требует инструментирования кода с операторами POST","Зависит от пользователя, воспроизводящего ошибку","Требует установки CLI clog"],"ar":["يتطلب تشغيل خادم clog محلياً","يحتاج إلى أداة تعليم البرمجة بجمل POST","يعتمد على المستخدم لإعادة إنتاج الخطأ","يتطلب تثبيت CLI clog"]},"version":3},"contentHash":"d452ac7c230fd9e1b40a2097334b8ea8599a1f7c1129cdebc8ce8115a1663bb1","qualityScore":37}');
